import Foundation
import PDFKit
import OfficePdfKernel
import Darwin

// 公开内核级验收入口。CI只编译/链接；没有UIKit生命周期、UTS回调或强取消实现。
private enum HarnessError: Error, CustomStringConvertible {
    case invalid(String)
    var description: String {
        switch self { case .invalid(let message): return message }
    }
}

private struct NativeResponse {
    let text: String
    let data: Data
    let object: [String: Any]
}

private struct Request: Encodable {
    let inputPath: String
    let outputPath: String
    let resourcePath: String
    let profilePath: String
    let format: String
    let deadlineUptimeMs: Double
    // 仅调用方关联；当前C内核不读取、校验或回传此字段。
    let taskId: String

    func encoded() throws -> String {
        for path in [inputPath, outputPath, resourcePath, profilePath] {
            guard path.hasPrefix("/"), !path.utf8.contains(0) else {
                throw HarnessError.invalid("请求路径必须是无NUL绝对路径")
            }
        }
        guard ["docx", "pptx"].contains(format), inputPath != outputPath,
              deadlineUptimeMs.isFinite, deadlineUptimeMs > 0,
              !FileManager.default.fileExists(atPath: outputPath) else {
            throw HarnessError.invalid("格式、期限或独占输出路径不合法")
        }
        let bytes = try JSONEncoder().encode(self)
        guard bytes.count <= 65536, let text = String(data: bytes, encoding: .utf8) else {
            throw HarnessError.invalid("请求必须是至多65536字节的UTF-8 JSON")
        }
        return text
    }
}

private struct Probe: Decodable {
    let available: Bool
    let strictOffline: Bool
    let supportsHardCancel: Bool
    let testOnly: Bool
    let acceptanceOnly: Bool
    let offlinePolicySha256: String
    let engine: String
    let engineVersion: String
    let sourceTag: String
    let nativeCode: String
}

private struct ResponseType: Decodable { let type: String }
private struct ProductionRejection: Decodable {
    let type: String
    let reason: String
    let nativeCode: String
}
private struct AcceptanceSuccess: Decodable {
    let type: String
    let sourceFormat: String
    let released: Bool
    let testOnly: Bool
}
private struct FailureCode: Decodable { let nativeCode: String? }

private struct Identity: Decodable {
    struct Producer: Decodable {
        let sourceCommit: String
        let runId: String
        let runAttempt: String
    }
    struct Consumer: Decodable {
        let sourceCommit: String
        let runId: String
        let runAttempt: String
        let jobName: String
    }
    let format: String
    let producer: Producer
    let consumer: Consumer
    let candidateManifestSha256: String
    let candidateInventorySha256: String
    let acceptanceOnly: Bool
    let testOnly: Bool
    let runtimeExecuted: Bool
}

private final class Report {
    let directory: URL
    private let destination: URL
    private var events: [[String: Any]] = []
    private var result = "running"
    private let reportId = UUID().uuidString

    init(directory: URL) {
        self.directory = directory
        destination = directory.appendingPathComponent("report.json")
    }

    func append(_ stage: String, _ details: [String: Any] = [:]) throws {
        events.append(["stage": stage, "time": ISO8601DateFormatter().string(from: Date()),
                       "uptimeMs": ProcessInfo.processInfo.systemUptime * 1000.0,
                       "details": details])
        try persist()
    }

    func finish(_ status: String) throws {
        result = status
        try persist()
    }

    private func persist() throws {
        let value: [String: Any] = [
            "format": "office-pdf-ios-abi-runtime-report-v1", "reportId": reportId,
            "result": result, "testOnly": true, "scope": "public-kernel-c-abi",
            "supportsHardCancel": false, "taskIdSource": "harness-owned-not-returned-by-C",
            "runtimeBoundary": "该报告仅在实际启动本程序后产生；不证明UTS、基座、四格式或严格离线资格",
            "unverified": ["DOC/PPT旧格式", "文档内容/字体/分页准确性", "UTS与私有Bridge调用链",
                           "UIKit生命周期和签名安装", "恶意样本/外链与流量观测", "强取消与阻塞回收"],
            "profileLifetime": "Kit及固定profile保留到进程退出；document释放不等于engine销毁",
            "events": events
        ]
        let data = try JSONSerialization.data(withJSONObject: value, options: [.prettyPrinted, .sortedKeys])
        // 仅重写本次独占报告；不覆盖转换输出，不删除长期profile。
        try data.write(to: destination, options: .atomic)
        FileHandle.standardOutput.write(data)
        FileHandle.standardOutput.write(Data([10]))
    }
}

@main
struct KernelAbiAcceptance {
    private static let policySHA = "cde377b7ed192031a6ff153108cea97f4f839d9009b0990d2da8f173328bbc15"
    private static let manifestSHA = "bd2e818e4f43a1ffa5c09e470dbf7b77e1d50d22324baf1dea6dcc2fc97556f5"
    private static let inventorySHA = "98f64285f0e51a99c22ba49eee03afeed8b92e83e888b1132966bce39c9886a1"

    static func main() {
        var report: Report?
        do {
            let files = FileManager.default
            let support = try files.url(for: .applicationSupportDirectory, in: .userDomainMask,
                                        appropriateFor: nil, create: true)
                .appendingPathComponent("OfficePdfKernelAcceptance", isDirectory: true)
            try files.createDirectory(at: support, withIntermediateDirectories: true)
            let runs = support.appendingPathComponent("Runs", isDirectory: true)
            try files.createDirectory(at: runs, withIntermediateDirectories: true)
            let run = runs.appendingPathComponent(UUID().uuidString, isDirectory: true)
            // 独占创建；碰撞时失败，不复用既有任务/输出。
            try exclusiveDirectory(run)
            let current = Report(directory: run)
            report = current
            try current.append("started", ["execution": "synchronous-serial", "pid": ProcessInfo.processInfo.processIdentifier])
            let succeeded = try execute(report: current, support: support)
            if !succeeded { exit(EXIT_FAILURE) }
        } catch {
            let details: [String: Any] = ["harnessErrorType": String(reflecting: type(of: error)),
                                         "harnessError": String(describing: error)]
            if let current = report {
                do { try current.append("harness-failure", details); try current.finish("failed") }
                catch { emitReportFailure(error, original: details) }
            } else { emitReportFailure(error, original: details) }
            exit(EXIT_FAILURE)
        }
    }

    private static func emitReportFailure(_ error: Error, original: [String: Any]) {
        // 文件系统不可写时仍输出真实本地错误；不伪造nativeCode或内核响应。
        let envelope: [String: Any] = ["scope": "harness-report-write", "testOnly": true,
                                      "original": original, "reportError": String(describing: error)]
        do {
            let data = try JSONSerialization.data(withJSONObject: envelope, options: [.sortedKeys])
            FileHandle.standardError.write(data)
            FileHandle.standardError.write(Data([10]))
        } catch {
            FileHandle.standardError.write(Data(("harness报告序列化失败: " + String(describing: error) + "\n").utf8))
        }
    }

    private static func decodeOwned(_ raw: UnsafePointer<CChar>?) throws -> NativeResponse {
        guard let owned = raw else { throw HarnessError.invalid("C ABI返回NULL，无可释放响应") }
        defer { OfficePdfKernelFreeString(owned) }
        guard let text = String(validatingUTF8: owned) else {
            throw HarnessError.invalid("C ABI返回非法UTF-8")
        }
        let data = Data(text.utf8)
        let parsed: Any
        do { parsed = try JSONSerialization.jsonObject(with: data) }
        catch { throw HarnessError.invalid("C ABI JSON解析失败: \(error)；原始UTF-8响应: \(text)") }
        guard let object = parsed as? [String: Any] else {
            throw HarnessError.invalid("C ABI响应不是JSON对象；原始UTF-8响应: " + text)
        }
        return NativeResponse(text: text, data: data, object: object)
    }

    private static func readIdentity(_ app: URL) throws -> [String: Any] {
        let path = app.appendingPathComponent("HarnessIdentity.json")
        let bytes = try Data(contentsOf: path)
        guard bytes.count <= 1024 * 1024, String(data: bytes, encoding: .utf8) != nil else {
            throw HarnessError.invalid("HarnessIdentity必须是有界UTF-8 JSON")
        }
        let identity = try JSONDecoder().decode(Identity.self, from: bytes)
        let consumer = identity.consumer
        guard identity.format == "office-pdf-ios-abi-harness-v1",
              identity.producer.sourceCommit == "5d8083b9e6aeba055d0ae58761271e5341f04bb2",
              identity.producer.runId == "40131160579", identity.producer.runAttempt == "1",
              consumer.sourceCommit.count == 40,
              consumer.sourceCommit.allSatisfy({ "0123456789abcdef".contains($0) }),
              consumer.sourceCommit != identity.producer.sourceCommit,
              isPositiveInteger(consumer.runId), isPositiveInteger(consumer.runAttempt),
              !consumer.jobName.isEmpty,
              identity.candidateManifestSha256 == manifestSHA,
              identity.candidateInventorySha256 == inventorySHA,
              identity.acceptanceOnly, identity.testOnly, !identity.runtimeExecuted,
              let object = try JSONSerialization.jsonObject(with: bytes) as? [String: Any] else {
            throw HarnessError.invalid("HarnessIdentity与已核producer/consumer合同不匹配")
        }
        // runtimeExecuted=false只描述构建期未执行，不被用作当前运行成功证据。
        return object
    }

    private static func isPositiveInteger(_ text: String) -> Bool {
        return !text.isEmpty && text.utf8.allSatisfy({ $0 >= 48 && $0 <= 57 }) && text.utf8.contains(where: { $0 != 48 })
    }

    private static func regularFile(_ url: URL) throws {
        let values = try url.resourceValues(forKeys: [.isRegularFileKey, .isSymbolicLinkKey, .fileSizeKey])
        guard values.isRegularFile == true, values.isSymbolicLink == false,
              let size = values.fileSize, size > 0 else {
            throw HarnessError.invalid("必须是非空普通文件: " + url.lastPathComponent)
        }
    }

    private static func exclusiveDirectory(_ url: URL) throws {
        // Foundation的createDirectory会接受已存在目录，不能用它证明任务目录独占。
        let status = url.path.withCString { mkdir($0, mode_t(0o700)) }
        guard status == 0 else { throw HarnessError.invalid("独占mkdir失败，errno=\(errno)") }
    }

    private static func execute(report: Report, support: URL) throws -> Bool {
        let app = Bundle.main.bundleURL
        let identity = try readIdentity(app)
        try report.append("identity", ["buildIdentity": identity, "runtimeExecutionStarted": true])
        let resources = app.appendingPathComponent("OfficePdfKernelResources.bundle", isDirectory: true)
        let resourceValues = try resources.resourceValues(forKeys: [.isDirectoryKey, .isSymbolicLinkKey])
        guard resourceValues.isDirectory == true, resourceValues.isSymbolicLink == false else {
            throw HarnessError.invalid("资源bundle不是普通目录")
        }
        for name in ["rc", "fundamentalrc", "ICU.dat", "OfficePdfKernelManifest.json"] {
            try regularFile(resources.appendingPathComponent(name))
        }
        let profile = support.appendingPathComponent("Profile", isDirectory: true)
        try FileManager.default.createDirectory(at: profile, withIntermediateDirectories: true)
        let profileValues = try profile.resourceValues(forKeys: [.isDirectoryKey, .isSymbolicLinkKey])
        guard profileValues.isDirectory == true, profileValues.isSymbolicLink == false else {
            throw HarnessError.invalid("固定profile不是独立普通目录")
        }
        try regularFile(app.appendingPathComponent("ICU.dat"))

        try report.append("probe-start")
        let probeRaw: UnsafePointer<CChar>? = resources.path.withCString { OfficePdfKernelProbeJSON($0) }
        let probeResponse = try decodeOwned(probeRaw)
        try report.append("probe-response", ["native": probeResponse.object, "nativeJSON": probeResponse.text])
        let probe = try JSONDecoder().decode(Probe.self, from: probeResponse.data)
        guard !probe.available, !probe.strictOffline, !probe.supportsHardCancel,
              probe.testOnly, probe.acceptanceOnly, probe.offlinePolicySha256 == policySHA,
              probe.engine == "libreoffice", probe.engineVersion == "26.2.6.3",
              probe.sourceTag == "libreoffice-26.2.6.3", probe.nativeCode == "IOS_OFFLINE_POLICY_UNQUALIFIED" else {
            throw HarnessError.invalid("Probe真实字段与候选门禁不匹配")
        }

        var allSucceeded = true
        for (index, format) in ["docx", "pptx"].enumerated() {
            let taskId = UUID().uuidString
            let job = report.directory.appendingPathComponent("job-" + taskId, isDirectory: true)
            try exclusiveDirectory(job)
            let fixture = app.appendingPathComponent("Fixtures/sample." + format)
            try regularFile(fixture)
            let input = job.appendingPathComponent("sample." + format)
            try FileManager.default.copyItem(at: fixture, to: input)
            let output = job.appendingPathComponent("converted.pdf")
            let request = Request(inputPath: input.path, outputPath: output.path,
                                  resourcePath: resources.path, profilePath: profile.path,
                                  format: format,
                                  deadlineUptimeMs: (ProcessInfo.processInfo.systemUptime + 120.0) * 1000.0,
                                  taskId: taskId)
            let text = try request.encoded()
            if index == 0 {
                try report.append("production-negative-start", ["harnessTaskId": taskId, "format": format])
                let raw: UnsafePointer<CChar>? = text.withCString { OfficePdfKernelConvertJSON($0) }
                let rejection = try decodeOwned(raw)
                try report.append("production-negative-response", ["harnessTaskId": taskId,
                                  "native": rejection.object, "nativeJSON": rejection.text])
                let value = try JSONDecoder().decode(ProductionRejection.self, from: rejection.data)
                guard value.type == "fail", value.reason == "ENGINE_UNAVAILABLE",
                      value.nativeCode == "IOS_OFFLINE_POLICY_UNQUALIFIED" else {
                    throw HarnessError.invalid("生产负对照没有精确拒绝有效请求")
                }
            }

            try report.append("acceptance-start", ["harnessTaskId": taskId, "format": format,
                              "deadlineUptimeMs": request.deadlineUptimeMs, "requestBytes": text.utf8.count])
            let started = ProcessInfo.processInfo.systemUptime
            let raw: UnsafePointer<CChar>? = text.withCString { OfficePdfKernelAcceptanceConvertJSON($0) }
            let response = try decodeOwned(raw)
            try report.append("acceptance-response", ["harnessTaskId": taskId, "format": format,
                              "elapsedMs": (ProcessInfo.processInfo.systemUptime - started) * 1000.0,
                              "native": response.object, "nativeJSON": response.text])
            let type = try JSONDecoder().decode(ResponseType.self, from: response.data)
            if type.type == "fail" {
                allSucceeded = false
                let failure = try JSONDecoder().decode(FailureCode.self, from: response.data)
                if failure.nativeCode == "KERNEL_INIT_FAILED" {
                    try report.append("stopped-without-init-retry", ["harnessTaskId": taskId,
                                      "remainingFormatsNotRun": index == 0 ? ["pptx"] : []])
                    break
                }
                continue
            }
            guard type.type == "success" else { throw HarnessError.invalid("未知C响应type") }
            let success = try JSONDecoder().decode(AcceptanceSuccess.self, from: response.data)
            guard success.sourceFormat == format, success.released, success.testOnly else {
                throw HarnessError.invalid("验收成功响应缺少匹配sourceFormat/released/testOnly")
            }
            try regularFile(output)
            guard let document = PDFDocument(url: output), !document.isLocked, document.pageCount > 0 else {
                throw HarnessError.invalid("成功响应的实际输出不是非锁且有页的PDF")
            }
            try report.append("pdf-structure-checked", ["harnessTaskId": taskId,
                              "format": format, "pageCount": document.pageCount,
                              "contentAndPaginationAccuracyVerified": false])
        }
        try report.finish(allSucceeded ? "passed-kernel-structural-checks-only" : "native-failure-observed")
        return allSucceeded
    }
}

