def link_parser():
    # 只复用纯ar/Mach-O函数；不得使用SW恢复/receipt/缺失容忍入口。
    spec = importlib.util.spec_from_file_location('office_pdf_pure_link_parser', ROOT / 'ci/inspect_link.py')
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


class MappedArchive:
    """只读mmap的bytes接口；ar解析器逐成员复制，避免整库重复驻留。"""
    def __init__(self, mapping):
        self.mapping = mapping

    def __len__(self):
        return len(self.mapping)

    def __getitem__(self, key):
        return self.mapping[key]

    def startswith(self, prefix):
        return self.mapping[:len(prefix)] == prefix


def native_members(path, max_bytes=MAX_LINK_INPUT):
    parser = link_parser()
    if path.is_symlink() or not path.is_file() or not 0 < path.stat().st_size <= max_bytes:
        raise ValueError('原生输入缺失/链接/体积超限: ' + str(path))
    with path.open('rb') as stream, mmap.mmap(stream.fileno(), 0, access=mmap.ACCESS_READ) as mapping:
        data = MappedArchive(mapping)
        if data.startswith(b'!<arch>\n'):
            yield from parser.archive_members(data, max_bytes=max_bytes, max_members=MAX_LINK_MEMBERS)
        else:
            raw = mapping[:]
            yield {'index': 1, 'occurrence': 1, 'name': path.name, 'bytes': len(raw),
                   'sha256': hashlib.sha256(raw).hexdigest(), 'data': raw}


def scan_link_inputs(inputs, build):
    parser, rows, total, count = link_parser(), [], 0, 0
    if len(inputs) > 2000 or len(inputs) != len(set(inputs)):
        raise ValueError('原生输入数超限或存在物理重复路径')
    for path in inputs:
        total += path.stat().st_size
        if total > MAX_LINK_TOTAL:
            raise ValueError('完整静态输入总字节超限')
        before = sha256(path)
        row = {'path': str(path), 'bytes': path.stat().st_size, 'sha256': before, 'members': []}
        for member in native_members(path):
            symbols = parser.macho_symbols(member['data'])
            row['members'].append({**{k:v for k,v in member.items() if k != 'data'}, 'symbols': symbols})
            count += 1
            if count > MAX_LINK_MEMBERS:
                raise ValueError('完整静态成员数超限')
        if not row['members']:
            raise ValueError('空archive无法证明arm64输入: ' + str(path))
        if sha256(path) != before:
            raise ValueError('扫描期间输入身份变化: ' + str(path))
        rows.append(row)
    return rows


def member_counter(rows):
    return collections.Counter((m['bytes'], m['sha256']) for row in rows for m in row['members'])


def symbol_union(rows, kind):
    return {s for row in rows for member in row['members'] for s in member['symbols'][kind]}


def normalize_ios_link_inputs(inputs, build, rows):
    """仅精确路径候选排除，所有业务依赖由联合after图再次证明。"""
    unpacked = 'workdir/UnpackedTarball/'
    pairs = [('curl', 'curl/lib/.libs/libcurlu.a', 'curl/lib/.libs/libcurl.a')]
    pairs += [(name, f'{folder}/src/lib/.libs/{internal}', f'{folder}/src/lib/.libs/{public}') for name,folder,internal,public in (
        ('cdr','libcdr','libcdr-internal.a','libcdr-0.1.a'),
        ('visio','libvisio','libvisio-internal.a','libvisio-0.1.a'),
        ('epubgen','libepubgen','libepubgen_internal.a','libepubgen-0.1.a'))]
    pairs += [('sharpyuv-' + cpu, 'libwebp/sharpyuv/.libs/libsharpyuv_' + cpu + '.a',
               'libwebp/sharpyuv/.libs/libsharpyuv.a') for cpu in ('neon','sse2')]
    by_path = {pathlib.Path(row['path']): row for row in rows}
    removed, rules = set(), []
    for name, old, canonical in pairs:
        old, canonical = build / (unpacked + old), build / (unpacked + canonical)
        if old not in inputs:
            continue
        if canonical not in inputs:
            raise ValueError('缺少canonical正式库: ' + str(canonical))
        if name == 'curl':
            if not symbol_union([by_path[canonical]], 'strong') <= symbol_union([by_path[old]], 'strong'):
                raise ValueError('curl UNITTESTS副本未覆盖正式库强定义')
        elif member_counter([by_path[old]]) - member_counter([by_path[canonical]]):
            raise ValueError('便利库成员多重集未被canonical包含: ' + name)
        removed.add(old)
        rules.append({'family': name, 'excluded': str(old.relative_to(build)),
                      'canonical': str(canonical.relative_to(build)), 'memberContainment': name != 'curl'})
    for family, relatives in (
            ('nss', [unpacked + 'nss/nss/lib/freebl/out/libfreebl.a']),
            ('uno', ['instdir/program/libnet_uno.a','instdir/program/libunsafe_uno_uno.a']),
            ('icu', [unpacked + 'icu/source/lib/libicudata.a'])):
        for relative in relatives:
            path = build / relative
            if path in inputs:
                removed.add(path)
                rules.append({'family': family, 'excluded': relative, 'requiresFinalContract': True})
    return [p for p in inputs if p not in removed], rules


def symbol_summary(values):
    ordered = sorted(values)
    return {'count': len(ordered), 'sha256': hashlib.sha256(json.dumps(ordered, separators=(',', ':'), ensure_ascii=False).encode()).hexdigest()}


def file_identity(path, root):
    if path.is_symlink() or not path.resolve().is_relative_to(root.resolve()) or not path.is_file() or path.stat().st_size>MAX_LINK_INPUT:
        raise ValueError('必要文件缺失/路径逃逸: ' + str(path))
    return {'path':str(path),'bytes':path.stat().st_size,'sha256':sha256(path)}


def validate_link_profile(source, build):
    text=(build/'config_host.mk').read_text(encoding='utf-8')
    expected={'OS':'iOS','CPUNAME':'AARCH64','CPPU_ENV':'gcc3','DISABLE_DYNLOADING':'TRUE','ENABLE_DOTNET':'TRUE'}
    for key,value in expected.items():
        matches=re.findall(r'^(?:export\s+)?'+key+r'\s*(?::?=)\s*([^\n]*)$',text,re.MULTILINE)
        if matches != [value]:
            raise ValueError('最终链接profile配置不匹配: '+key)
    files=[file_identity(build/'config_host.mk',build)]
    for origin,relative,wanted in LINK_SOURCE_SHA256:
        root=source if origin=='source' else build
        entry=file_identity(root/relative,root)
        if entry['sha256']!=wanted:
            raise ValueError('静态分派/ICU/NSS固定源码身份变化: '+relative)
        files.append(entry)
    return {'values':expected,'files':files}


def validate_ios_families(rows, selected, build, resources):
    """完整make后对NSS后端、UNO静态分派及ICU外部数据分别闭环。"""
    by_path={pathlib.Path(row['path']):row for row in rows}
    selected=set(selected)
    def require(relative, retained=True):
        path=build/relative
        if path not in by_path or (retained and path not in selected):
            raise ValueError('必要final输入缺失或被排除: '+relative)
        return by_path[path]
    prefix='workdir/UnpackedTarball/'
    for folder,public,internal in (
            ('curl/lib','libcurl.a','libcurlu.a'),('libcdr/src/lib','libcdr-0.1.a','libcdr-internal.a'),
            ('libvisio/src/lib','libvisio-0.1.a','libvisio-internal.a'),
            ('libepubgen/src/lib','libepubgen-0.1.a','libepubgen_internal.a'),
            ('libwebp/sharpyuv','libsharpyuv.a','libsharpyuv_neon.a'),
            ('libwebp/sharpyuv','libsharpyuv.a','libsharpyuv_sse2.a')):
        require(prefix+folder+'/.libs/'+public)
        require(prefix+folder+'/.libs/'+internal,False)
    nss=prefix+'nss/nss/lib/freebl/out/'
    parent=require(nss+'libfreebl.a',False)
    child_dir=build/(nss+'Darwin_SINGLE_SHLIB')
    # 只列两个已知后端目录，不扫整个构建树；目录中的实际root/deprecated对象全部保留。
    child_paths=sorted(child_dir.glob('*.o'))+sorted((child_dir/'deprecated').glob('*.o'))
    if not child_paths or len(child_paths)>1000:
        raise ValueError('NSS真实后端对象缺失/超限')
    for path in child_paths:
        file_identity(path,build)
        if path not in selected:
            raise ValueError('NSS raw root/deprecated对象遗漏: '+str(path))
    for name in ('deprecated/alg2268.o','deprecated/seed.o'):
        require(nss+'Darwin_SINGLE_SHLIB/'+name)
    paired=[]
    if len(parent['members'])!=13 or sum(m['name']=='loader.o' for m in parent['members'])!=1:
        raise ValueError('NSS父archive不再是loader+十二libcrux对象')
    for member in parent['members']:
        if member['name']=='loader.o':continue
        child=require(nss+'Darwin_SINGLE_SHLIB/'+member['name'])
        if member_counter([{'members':[member]}]) != member_counter([child]):
            raise ValueError('NSS libcrux父/child成员bytes/SHA不一致')
        paired.append({'parentIndex':member['index'],'child':child['path'],'sha256':member['sha256']})
    nss_rows=[row for row in rows if pathlib.Path(row['path']).is_relative_to(child_dir) and pathlib.Path(row['path']) in selected]
    nss_strong=symbol_union(nss_rows,'strong')
    lifecycle={'_BL_Cleanup','_BL_SetForkState','_RNG_RNGShutdown','_FREEBL_GetVector','_DH_NewKey','_DH_Derive'}
    if not lifecycle <= nss_strong:
        raise ValueError('NSS真实生命周期/算法强定义遗漏: '+repr(sorted(lifecycle-nss_strong)))
    for bits in ('128','192','256'):
        for direction in ('enc','dec'):
            row=require(nss+'Darwin_SINGLE_SHLIB/aarch64-gcm-slothy/gcm-'+bits+'-'+direction+'.o')
            name='_aes_gcm_'+direction+'_kernel_slothy_base_'+bits
            if name not in symbol_union([row],'strong'):
                raise ValueError('NSS slothy真实算法入口遗漏: '+name)
    bridge=require('instdir/program/libgcc3_uno.a')
    for name in ('libnet_uno.a','libunsafe_uno_uno.a'):require('instdir/program/'+name,False)
    # 固定component宏使用完整字面token；CPPU_ENV=gcc3决定库名，不展开标识符内部前缀。
    entries={'lbenv':'_CPPU_ENV_uno_initEnvironment','lbmap':'_CPPU_ENV_uno_ext_getMapping'}
    cpp_rows=[]
    for file,symbol in entries.items():
        path=build/('workdir/CxxObject/cppu/source/uno/'+file+'.o')
        identity=file_identity(path,build)
        matches=[(row,m) for row in rows if pathlib.Path(row['path']) in selected for m in row['members']
                 if m['bytes']==identity['bytes'] and m['sha256']==identity['sha256']]
        if not matches or not any(symbol in m['symbols']['undefined'] for _,m in matches):
            raise ValueError('UNO编译dispatcher成员缺失或无真实静态引用: '+file)
        if symbol not in symbol_union([bridge],'strong'):
            raise ValueError('UNO真实C++ bridge静态入口缺失: '+symbol)
        cpp_rows.append({'sourceObject':identity,'staticEntry':symbol,'archive':matches[0][0]['path'],
                         'memberIndex':matches[0][1]['index']})
    icu=prefix+'icu/source/'
    embedded=require(icu+'lib/libicudata.a',False)
    stub=require(icu+'stubdata/libicudata.a')
    code=[require(icu+'lib/libicu'+name+'.a') for name in ('i18n','io','uc')]
    if symbol_union([stub],'strong')!={'_icudt78_dat'} or '_icudt78_dat' not in symbol_union(code,'undefined'):
        raise ValueError('ICU stub唯一强定义或真实代码引用无效')
    dat=build/(icu+'data/in/icudt78l.dat')
    source_dat=file_identity(dat,build)
    staged=file_identity(resources/'ICU.dat',resources)
    if (source_dat['bytes'],source_dat['sha256'])!=ICU_DATA_IDENTITY:
        raise ValueError('ICU固定官方icudt78l.dat身份不匹配')
    if not source_dat['bytes'] or (source_dat['bytes'],source_dat['sha256'])!=(staged['bytes'],staged['sha256']):
        raise ValueError('ICU官方data/in与最终staged ICU.dat不一致')
    payloads=[]
    for member in native_members(pathlib.Path(embedded['path'])):
        if '_icudt78_dat' in link_parser().macho_symbols(member['data'])['strong']:
            payload=macho_symbol_payload(member['data'],'_icudt78_dat')
            payloads.append({'bytes':len(payload),'sha256':hashlib.sha256(payload).hexdigest(),
                             'memberIndex':member['index']})
    if len(payloads)!=1 or (payloads[0]['bytes'],payloads[0]['sha256'])!=(source_dat['bytes'],source_dat['sha256']):
        raise ValueError('ICU embedded符号payload与完整外部数据不一致')
    identities=[source_dat,staged,*[entry['sourceObject'] for entry in cpp_rows]]
    return {'nss':{'libcruxPairs':len(paired),'pairs':paired,'lifecycle':sorted(lifecycle)},
            'uno':{'compiledDispatch':cpp_rows},'icu':{'bytes':source_dat['bytes'],'sha256':source_dat['sha256'],
            'source':source_dat,'staged':staged,'embeddedPayload':payloads[0]},'identityFiles':identities}


def audit_input_graph(rows, selected, public_roots=()):
    selected = {str(p) for p in selected}
    after = [row for row in rows if row['path'] in selected]
    excluded = [row for row in rows if row['path'] not in selected]
    definitions = collections.Counter(s for row in after for m in row['members'] for s in m['symbols']['strong'])
    duplicates = sorted(s for s,n in definitions.items() if n > 1)
    if duplicates:
        raise ValueError('after存在重复强定义: ' + repr(duplicates[:20]))
    before_sets = {k: symbol_union(rows,k) for k in SYMBOL_KINDS}
    after_sets = {k: symbol_union(after,k) for k in SYMBOL_KINDS}
    refs = after_sets['undefined'] | after_sets['weakUndefined'] | set(public_roots)
    lost = {}
    retained_members = member_counter(after)
    for kind in ('strong','weak','common'):
        # strong只有同名不能证明common数组的尺寸/对齐；本实现保守要求原对象仍在。
        provided = set() if kind=='common' else after_sets['strong'] | (after_sets['weak'] if kind == 'weak' else set())
        # common的尺寸/对齐未由纯parser公开，只有原对象逐字节仍保留才能证明。
        same_objects = {s for row in excluded for m in row['members']
                        if retained_members[(m['bytes'],m['sha256'])] for s in m['symbols'][kind]}
        lost[kind] = symbol_union(excluded,kind) - provided - same_objects
        downgrades = lost[kind] & (after_sets['weak'] | after_sets['common']) if kind == 'strong' else lost[kind] & after_sets['common']
        if downgrades or (lost[kind] & refs) or (kind == 'common' and lost[kind]):
            raise ValueError('排除定义丢失或降级(' + kind + '): ' + repr(sorted(downgrades | (lost[kind] & refs) | (lost[kind] if kind == 'common' else set()))[:20]))
    missing_roots = set(public_roots) - after_sets['strong']
    if missing_roots:
        raise ValueError('公开/注册根缺少真实强定义: ' + repr(sorted(missing_roots)))
    return {'before': {k:symbol_summary(v) for k,v in before_sets.items()},
            'after': {k:symbol_summary(v) for k,v in after_sets.items()},
            'lostDefinitions': {k:{**symbol_summary(v), 'symbols':sorted(v)} for k,v in lost.items()},
            'duplicateStrong': [], 'excludedConsumers': []}


def macho_symbol_payload(data, symbol):
    """按真实arm64 MH_OBJECT节和符号extent提取数据，所有偏移先验界。"""
    symbols = link_parser().macho_symbols(data)
    if symbol not in symbols['strong']:
        raise ValueError('ICU数据对象缺少强定义: ' + symbol)
    sections, symtab, cursor = [], None, 32
    ncmds, sizeofcmds = struct.unpack_from('<II', data, 16)
    for _ in range(ncmds):
        cmd,size = struct.unpack_from('<II',data,cursor)
        if cmd == 0x19:
            if size < 72:
                raise ValueError('Mach-O segment长度无效')
            nsects = struct.unpack_from('<I',data,cursor+64)[0]
            if 72 + nsects*80 != size:
                raise ValueError('Mach-O section表长度无效')
            for i in range(nsects):
                off=cursor+72+i*80
                address,length,file_offset=struct.unpack_from('<QQI',data,off+32)
                flags=struct.unpack_from('<I',data,off+64)[0]
                sections.append((address,length,file_offset,flags))
        elif cmd == 2:
            symtab=struct.unpack_from('<IIII',data,cursor+8)
        cursor += size
    if cursor != 32+sizeofcmds or symtab is None:
        raise ValueError('Mach-O数据命令无效')
    offset,count,stroff,strsize=symtab
    definitions=[]
    for i in range(count):
        index,kind,sect,desc,value=struct.unpack_from('<IBBHQ',data,offset+i*16)
        if kind & 0xe0 or (kind & 0xe) != 0xe:
            continue
        if index >= strsize or not 1 <= sect <= len(sections):
            raise ValueError('Mach-O数据符号索引越界')
        end=data.find(b'\0',stroff+index,stroff+strsize)
        if end < 0:
            raise ValueError('Mach-O数据符号名未终止')
        definitions.append((data[stroff+index:end].decode('utf-8'),sect,value))
    matches=[entry for entry in definitions if entry[0] == symbol]
    if len(matches)!=1:
        raise ValueError('ICU数据符号不是唯一实际定义')
    _,sect,value=matches[0]
    address,length,file_offset,flags=sections[sect-1]
    if flags & 0xff or not address <= value < address+length or file_offset+length > len(data):
        raise ValueError('Mach-O数据section长度或类型越界')
    end=min([v for _,s,v in definitions if s==sect and v>value]+[address+length])
    start=file_offset+value-address
    if end<=value or start+end-value>len(data):
        raise ValueError('Mach-O数据payload越界')
    return data[start:start+end-value]


def verify_aggregate(archive, expected):
    counter=collections.Counter((m['bytes'],m['sha256']) for m in native_members(archive, MAX_LINK_TOTAL))
    wanted=member_counter(expected)
    if counter != wanted:
        raise ValueError('aggregate成员多重集与selected+shim/registration不一致')
    return {'bytes':archive.stat().st_size,'sha256':sha256(archive),'members':sum(counter.values()),
            'memberMultisetSha256':hashlib.sha256(json.dumps(sorted((n,s,c) for (n,s),c in counter.items()),separators=(',',':')).encode()).hexdigest(),
            'verified':True}


class LinkAudit:
    """长原生命令前原子落盘，SIGKILL后仍能读取最后完整阶段。"""
    def __init__(self, directory):
        if directory.is_symlink() or (directory.exists() and (not directory.is_dir() or any(directory.iterdir()))):
            raise ValueError('audit-directory必须是新空普通目录')
        directory.mkdir(parents=True,exist_ok=True)
        self.directory=directory.resolve(strict=True)
        self.value={'format':'office-pdf-ios-final-link-audit-v1','phase':'starting','complete':False,
                    'inputAuditComplete':False,'aggregateAuditComplete':False,'referenceUniverseComplete':False,
                    'appleLinkVerified':False,'linkMap':None,'linkMapPlanned':False}
        self.update('starting')

    def update(self, phase, **fields):
        updated={**self.value,**fields,'phase':phase}
        raw=(json.dumps(updated,ensure_ascii=False,separators=(',',':'))+'\n').encode('utf-8')
        if len(raw)>MAX_AUDIT_BYTES:
            raise ValueError('AUDIT.json超过8MiB，拒绝截断')
        path=self.directory/'AUDIT.json'
        if path.is_symlink() or (path.exists() and not path.is_file()) or self.directory.is_symlink():
            raise ValueError('审计输出路径发生变化')
        with tempfile.NamedTemporaryFile(mode='wb',dir=self.directory,prefix='.audit-',delete=False) as stream:
            temporary=pathlib.Path(stream.name)
            try:
                stream.write(raw);stream.flush();os.fsync(stream.fileno())
            except BaseException:
                temporary.unlink(missing_ok=True)
                raise
        try:
            os.replace(temporary,path)
            self.value=updated
        finally:
            temporary.unlink(missing_ok=True)

    def capture_map(self):
        path=self.directory/'link-map.log'
        directory=self.directory.lstat()
        if not stat.S_ISDIR(directory.st_mode) or self.directory.resolve(strict=True)!=self.directory:
            raise ValueError('link-map.log父目录不是固定普通目录')
        try:
            before=path.lstat()
        except FileNotFoundError:
            return None
        def checked_identity(info):
            if not stat.S_ISREG(info.st_mode) or info.st_nlink!=1:
                raise ValueError('link-map.log不是独立普通文件')
            if info.st_size>MAX_LINK_MAP:
                raise ValueError(f'link-map.log原文体积超限：bytes={info.st_size}，limit={MAX_LINK_MAP}')
            return (info.st_dev,info.st_ino,info.st_size,info.st_mtime_ns,info.st_ctime_ns)
        identity=checked_identity(before)
        # 同一fd逐块摘要；NOFOLLOW/NONBLOCK避免检查与打开之间换入链接或FIFO。
        flags=os.O_RDONLY|getattr(os,'O_BINARY',0)|getattr(os,'O_NOFOLLOW',0)|getattr(os,'O_NONBLOCK',0)
        with os.fdopen(os.open(path,flags),'rb') as stream:
            if checked_identity(os.fstat(stream.fileno()))!=identity:
                raise ValueError('打开期间link-map.log身份变化')
            digest=hashlib.sha256()
            total=0
            while True:
                raw=stream.read(min(1024**2,MAX_LINK_MAP-total+1))
                if not raw:
                    break
                total+=len(raw)
                if total>MAX_LINK_MAP:
                    # 文件仍可能增长或截断；同fd的瞬时大小与已读前缀必须分开记录。
                    observed=os.fstat(stream.fileno()).st_size
                    raise ValueError(f'读取期间link-map.log原文/读取体积超限：bytes={observed}（同fd当前观测，非最终稳定大小），readBytes={total}，limit={MAX_LINK_MAP}')
                digest.update(raw)
            if checked_identity(os.fstat(stream.fileno()))!=identity or total!=before.st_size:
                raise ValueError('读取期间link-map.log身份/大小变化')
        # fd关闭后再次核对路径与父目录，不能为已被替换的路径返回旧文件摘要。
        after_directory=self.directory.lstat()
        if (checked_identity(path.lstat())!=identity or self.directory.resolve(strict=True)!=self.directory or
                not stat.S_ISDIR(after_directory.st_mode) or
                (after_directory.st_dev,after_directory.st_ino)!=(directory.st_dev,directory.st_ino)):
            raise ValueError('读取后link-map.log路径/父目录身份变化')
        return {'path':'link-map.log','bytes':total,'sha256':digest.hexdigest()}


def compact_link_rows(rows):
    """完整成员身份保留；C++符号用五类counts和规范化SHA避免无界重复展开。"""
    inputs, members = [], []
    for i,row in enumerate(rows):
        inputs.append({k:v for k,v in row.items() if k!='members'})
        for member in row['members']:
            symbols=member['symbols']
            members.append([i,member['index'],member['occurrence'],member['name'],member['bytes'],member['sha256'],
                            [len(symbols[k]) for k in SYMBOL_KINDS],
                            hashlib.sha256(json.dumps([symbols[k] for k in SYMBOL_KINDS],ensure_ascii=False,separators=(',',':')).encode()).hexdigest()])
    return {'inputs':inputs,'memberColumns':['inputIndex','index','occurrence','name','bytes','sha256',
            'symbolCounts(strong,weak,common,undefined,weakUndefined)','symbolsSha256'], 'members':members}


def unchanged_identities(entries):
    for entry in entries:
        path=pathlib.Path(entry['path'])
        if path.is_symlink() or not path.is_file() or path.stat().st_size!=entry['bytes'] or sha256(path)!=entry['sha256']:
            raise ValueError('审计期间输入身份变化: '+entry['path'])

def gnu_make():
    # Homebrew安装的是gmake；macOS系统make通常较旧，不能混用。
    for name in ('gmake', 'make'):
        path = shutil.which(name)
        if not path:
            continue
        try:
            version = run([path, '--version'])
        except (OSError, subprocess.SubprocessError):
            continue
        match = re.search(r'^GNU Make (\d+)\.(\d+)', version, re.MULTILINE)
        if match and tuple(map(int, match.groups())) >= (4, 2):
            return {'path': path, 'version': version.splitlines()[0]}
    raise ValueError('固定上游要求GNU Make >=4.2；未找到可用的gmake/make')

def collector_makefile():
    # 与上游Makefile.in一致，先选择host，避免config_host.mk展开config__lang.mk。
    # config_host的外部库参数继续引用TargetLocations宏；须等WORKDIR已载入再展开，
    # 否则官方脚本会静默在/harfbuzz等根路径查库，遗漏字体整形及文档过滤依赖。
    return ('gb_Side := host\ninclude config_host.mk\n'
            'gb_UnpackedTarball_workdir := $(WORKDIR)/UnpackedTarball\n'
            'gb_StaticLibrary_WORKDIR := $(WORKDIR)/LinkTarget/StaticLibrary\n'
            '.PHONY: office_pdf_static_inputs office_pdf_source_identity\n'
            'office_pdf_source_identity:\n\t@printf "%s" "$(SRCDIR)"\n'
            'office_pdf_static_inputs:\n\t@$(SRCDIR)/bin/lo-all-static-libs\n')

def rebuild_patched_source(source, build, make, policy):
    raw_policy = (ROOT / 'offline-policy.json').read_bytes()
    if hashlib.sha256(raw_policy).hexdigest() != policy['policySha256']:
        raise ValueError('重建前策略清单变化')
    files = json.loads(raw_policy)['files']
    # 固定LinkTarget.mk的CxxObject依赖绝对SRCDIR路径。直接进入gbuild使-W作用于
    # 实际编译依赖图；不能交给顶层递归make后假定-W会传递给子make。
    command = [make['path'], '--no-print-directory', '-f', str(source / 'Makefile.gbuild'),
               'gb_Side=host', 'BUILDDIR=' + str(build)]
    for entry in files:
        command += ['--what-if=' + str(source / entry['path'])]
    command += ['build']
    config_sha = sha256(build / 'config_host.mk')
    # 必须真实执行并成功；不接受仅修改mtime、dry-run或旧archive的身份声明。
    # stdout/stderr保留给外层CI日志，不把大型原生构建日志吞入内存。
    subprocess.check_call(command, cwd=build)
    if validate_offline_policy(source) != policy or sha256(build / 'config_host.mk') != config_sha:
        raise ValueError('重建期间源码策略或构建配置身份变化')
    return {'command': command, 'succeeded': True, 'method': 'GNU make --what-if direct gbuild',
            'configHostSha256': config_sha,
            'forcedSources': [{'path': entry['path'], 'sha256': sha256(source / entry['path'])} for entry in files]}

def validate_offline_policy(source):
    spec = importlib.util.spec_from_file_location('office_pdf_offline_policy', ROOT / 'apply_offline_policy.py')
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    if (module.TAG, module.COMMIT) != (TAG, COMMIT):
        raise ValueError('构建器与离线策略固定身份不一致')
    return module.apply_or_verify(source, check=True)

def validate_build_compatibility(source):
    spec = importlib.util.spec_from_file_location('office_pdf_builder_compat', ROOT / 'build_compat.py')
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module.apply_or_verify(source, check=True)

def run(argv, cwd=None):
    return subprocess.check_output([str(x) for x in argv], cwd=cwd, text=True).strip()

def require_apple_tools():
    if sys.platform != 'darwin':
        raise RuntimeError('需要 macOS / Xcode；Windows只能运行源码/脚本回归')
    for tool in ('clang++', 'libtool', 'lipo', 'vtool', 'nm'):
        run(['xcrun', '--find', tool])
    run(['xcodebuild', '-version'])

def sha256(path):
    digest = hashlib.sha256()
    with path.open('rb') as stream:
        while True:
            chunk = stream.read(1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
    return digest.hexdigest()

def inventory(root):
    root = pathlib.Path(root)
    result = []
    for path in sorted(root.rglob('*')):
        if path.is_symlink():
            raise ValueError('resource symlink refused: ' + str(path))
        if path.is_file():
            result.append({'path': path.relative_to(root).as_posix(), 'bytes': path.stat().st_size,
                           'sha256': sha256(path)})
        elif not path.is_dir():
            raise ValueError('non-regular resource: ' + str(path))
    if not result:
        raise ValueError('resources empty')
    return result

def validate_resource_layout(root):
    for name in ('program', 'share'):
        if not (root / name).is_dir():
            raise ValueError('expected iOS resource directory: ' + name)
    for name in ('rc', 'fundamentalrc', 'ICU.dat'):
        if not (root / name).is_file() or (root / name).stat().st_size == 0:
            raise ValueError('expected iOS bootstrap resource: ' + name)

def _resource_stat(value):
    return (value.st_dev, value.st_ino, value.st_mode, value.st_nlink, value.st_size,
            value.st_mtime_ns, value.st_ctime_ns)


def _resource_file(root, relative, limit=MAX_LINK_INPUT, contents=False):
    """同一fd分块核对普通文件；前后路径及所有父目录保持不变，拒绝链接/逃逸。"""
    if (not isinstance(relative, str) or not relative or '\\' in relative or '\x00' in relative or
            any(part in ('', '.', '..') for part in relative.split('/')) or relative.startswith('/')):
        raise ValueError('resource path invalid')
    root = pathlib.Path(root)
    parents = [root]
    for part in relative.split('/')[:-1]:
        parents.append(parents[-1] / part)
    parent_stats = []
    for parent in parents:
        info = parent.lstat()
        if not stat.S_ISDIR(info.st_mode) or parent.is_symlink() or parent.resolve() != parent.absolute():
            raise ValueError('resource directory symlink/escape')
        parent_stats.append(_resource_stat(info))
    path = root / relative
    before = path.lstat()
    if not stat.S_ISREG(before.st_mode) or before.st_nlink != 1 or not 0 <= before.st_size <= limit:
        raise ValueError('resource is not an independent bounded regular file')
    digest, chunks, total = hashlib.sha256(), [], 0
    descriptor = os.open(path, os.O_RDONLY | getattr(os, 'O_NOFOLLOW', 0) | getattr(os, 'O_BINARY', 0))
    with os.fdopen(descriptor, 'rb') as stream:
        if _resource_stat(os.fstat(stream.fileno())) != _resource_stat(before):
            raise ValueError('resource changed before read')
        while True:
            chunk = stream.read(65536)
            if not chunk:
                break
            total += len(chunk)
            if total > limit or total > before.st_size:
                raise ValueError('resource grew while reading')
            digest.update(chunk)
            if contents:
                chunks.append(chunk)
        after = os.fstat(stream.fileno())
    if (total != before.st_size or _resource_stat(before) != _resource_stat(after) or
            _resource_stat(path.lstat()) != _resource_stat(before) or
            [_resource_stat(parent.lstat()) for parent in parents] != parent_stats):
        raise ValueError('resource changed while reading')
    return {'path': relative, 'bytes': total, 'sha256': digest.hexdigest()}, b''.join(chunks)


def validate_compact_resources(bundle, main_root, manifest):
    """构建期核对新布局；运行时使用shim的独立mainBundle受控读取。"""
    keys = {'sourceTag', 'sourceCommit', 'offlinePolicy', 'buildCompatibility', 'layout', 'mainICU', 'resources'}
    if (not isinstance(manifest, dict) or set(manifest) != keys or manifest['sourceTag'] != TAG or
            manifest['sourceCommit'] != COMMIT or manifest['layout'] != COMPACT_RESOURCE_LAYOUT or
            not isinstance(manifest['offlinePolicy'], dict) or not isinstance(manifest['buildCompatibility'], dict)):
        raise ValueError('resource manifest identity/layout invalid')
    expected_main = {'path': 'ICU.dat', 'bytes': ICU_DATA_IDENTITY[0], 'sha256': ICU_DATA_IDENTITY[1]}
    if (not isinstance(manifest['mainICU'], dict) or manifest['mainICU'] != expected_main or
            type(manifest['mainICU'].get('bytes')) is not int):
        raise ValueError('resource manifest main ICU identity invalid')
    entries = manifest['resources']
    if not isinstance(entries, list) or not 0 < len(entries) <= 10000:
        raise ValueError('resource manifest inventory invalid')
    seen = set()
    for entry in entries:
        if (not isinstance(entry, dict) or set(entry) != {'path', 'bytes', 'sha256'} or
                not isinstance(entry['path'], str) or entry['path'] in seen or
                entry['path'] in (*COMPACT_EXCLUDED_RESOURCES, 'OfficePdfKernelManifest.json') or
                type(entry['bytes']) is not int or not 0 <= entry['bytes'] <= MAX_LINK_INPUT or
                not isinstance(entry['sha256'], str) or not re.fullmatch('[0-9a-f]{64}', entry['sha256'])):
            raise ValueError('resource manifest entry invalid')
        try:
            actual, _ = _resource_file(bundle, entry['path'])
        except OSError as error:
            raise ValueError('resource file missing/unreadable: ' + entry['path']) from error
        if actual != entry:
            raise ValueError('resource manifest file identity mismatch: ' + entry['path'])
        seen.add(entry['path'])
    # 除清单本身外，实际剩余文件须完整相等，不能接受漏项或三副本旧布局。
    actual = inventory(bundle)
    if {entry['path'] for entry in actual} != seen | {'OfficePdfKernelManifest.json'}:
        raise ValueError('resource manifest inventory incomplete')
    _, raw = _resource_file(bundle, 'OfficePdfKernelManifest.json', 4 * 1024**2, contents=True)
    if json.loads(raw.decode('utf-8')) != manifest:
        raise ValueError('resource manifest bytes mismatch')
    for name in ('rc', 'fundamentalrc'):
        if name not in seen or not next(entry['bytes'] for entry in entries if entry['path'] == name):
            raise ValueError('resource bootstrap missing/empty')
    for name in ('program', 'share'):
        if not (bundle / name).is_dir() or (bundle / name).is_symlink():
            raise ValueError('resource directory missing/unsafe')
    try:
        main, _ = _resource_file(main_root, 'ICU.dat')
    except OSError as error:
        raise ValueError('main ICU file missing/unreadable') from error
    if main != expected_main:
        raise ValueError('main ICU file identity mismatch')
    return main


def package_compact_resources(resources, output, original, commit, policy, compatibility):
    """保留完整输入，仅候选bundle排除两个固定根副本，主包保留原完整字节。"""
    for name in COMPACT_EXCLUDED_RESOURCES:
        try:
            identity, _ = _resource_file(resources, name)
        except (OSError, ValueError) as error:
            raise ValueError('ICU完整输入缺失/不安全: ' + name) from error
        if (identity['bytes'], identity['sha256']) != ICU_DATA_IDENTITY:
            raise ValueError('ICU完整输入身份不匹配: ' + name)
    if inventory(resources) != original or any(row['path'] == 'OfficePdfKernelManifest.json' for row in original):
        raise ValueError('完整资源输入身份变化或包含保留manifest')
    # 每项均经稳定读取；普通copytree保留空目录、所有字体/locale/gallery及元数据。
    for row in original:
        identity, _ = _resource_file(resources, row['path'])
        if identity != row:
            raise ValueError('resource input identity changed')
    bundle, main_root = output / 'OfficePdfKernelResources.bundle', output / 'AppRootResources'
    if bundle.exists() or main_root.exists():
        raise ValueError('resource output already exists')
    manifest = {'sourceTag': TAG, 'sourceCommit': commit, 'offlinePolicy': policy,
                'buildCompatibility': compatibility, 'layout': COMPACT_RESOURCE_LAYOUT,
                'mainICU': {'path': 'ICU.dat', 'bytes': ICU_DATA_IDENTITY[0], 'sha256': ICU_DATA_IDENTITY[1]},
                'resources': [row for row in original if row['path'] not in COMPACT_EXCLUDED_RESOURCES]}
    shutil.copytree(resources, bundle,
                    ignore=lambda directory, names: list(COMPACT_EXCLUDED_RESOURCES) if pathlib.Path(directory) == resources else [])
    (bundle / 'OfficePdfKernelManifest.json').write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    main_root.mkdir()
    shutil.copy2(resources / 'ICU.dat', main_root / 'ICU.dat')
    validate_compact_resources(bundle, main_root, manifest)
    if inventory(resources) != original:
        raise ValueError('resource input identity changed during package')
    return manifest, [file_identity(main_root / 'ICU.dat', output)]


def registration_inputs(build):
    paths = [build / 'workdir/CustomTarget/ios/native-code.h']
    paths += [build / 'config_host' / name for name in
              ('config_crypto.h', 'config_features.h', 'config_fuzzers.h', 'config_gpgme.h', 'config_locales.h')]
    for path in paths:
        if path.is_symlink() or not path.resolve().is_relative_to(build) or not path.is_file() or path.stat().st_size == 0:
            raise ValueError('missing/unsafe generated iOS registration input: ' + str(path))
    header = paths[0].read_text(encoding='utf-8')
    for symbol in ('lo_get_factory_map', 'lo_get_constructor_map'):
        if symbol not in header:
            raise ValueError('generated iOS registration header lacks ' + symbol)
    return [{'path': path.relative_to(build).as_posix(), 'bytes': path.stat().st_size, 'sha256': sha256(path)} for path in paths]

def validate_registration_symbols(symbols):
    for name in ('lo_get_factory_map', 'lo_get_constructor_map'):
        if '_' + name not in symbols.splitlines():
            raise ValueError('registration object lacks unmangled C symbol: ' + name)

def link_inputs(text, build):
    result = []
    for item in shlex.split(text):
        path = pathlib.Path(item)
        if not path.is_absolute():
            path = build / path
        if '*' in str(path) or '?' in str(path) or path.suffix not in ('.a', '.o'):
            raise ValueError('unexpanded/malformed native input: ' + item)
        path = path.resolve()
        if not path.is_relative_to(build) or not path.is_file():
            raise ValueError('native input outside build: ' + item)
        if path not in result:
            result.append(path)
    if not result:
        raise ValueError('empty LibreOffice static inputs')
    return result

def ios_link_inputs(text, build):
    # 固定LO 26.2.6.3的lo-all-static-libs全集继续保留；这里只补官方
    # RepositoryExternal.mk及NSS3.128 freebl/Makefile中已确认的漏项。
    # 不扫全树、不选内部替代archive；缺失/逃逸沿用同一失败门禁。
    build = build.resolve(strict=True)
    inputs = link_inputs(text, build)
    unpacked = build / 'workdir/UnpackedTarball'
    configured = ('harfbuzz/builddir/src/libharfbuzz.a',)
    expected = link_inputs(shlex.join(str(unpacked / name) for name in configured), build)
    if any(path not in inputs for path in expected):
        raise ValueError('官方静态收集器遗漏配置依赖；须检查gbuild路径展开')
    # m4内部模式的EBOOK_LIBS/FREEHAND_LIBS为空；RepositoryExternal直接加这两库，
    # 不能误要求它们必须已在lo-all-static-libs基于环境变量的输出中。
    supplemental = ['libebook/src/lib/.libs/libe-book-0.1.a',
                    'libfreehand/src/lib/.libs/libfreehand-0.1.a',
                    'libetonyek/src/lib/.libs/libetonyek-0.1.a',
                    'libpagemaker/src/lib/.libs/libpagemaker-0.0.a',
                    'libstaroffice/src/lib/.libs/libstaroffice-0.0.a',
                    'libqxp/src/lib/.libs/libqxp-0.0.a',
                    'libzmf/src/lib/.libs/libzmf-0.0.a',
                    'libxslt/libexslt/.libs/libexslt.a']
    supplemental += ['nss/nss/lib/freebl/out/Darwin_SINGLE_SHLIB/aarch64-gcm-slothy/gcm-' + bits + '-' + direction + '.o'
                     for bits in ('128', '192', '256') for direction in ('enc', 'dec')]
    for path in link_inputs(shlex.join(str(unpacked / name) for name in supplemental), build):
        if path not in inputs:
            inputs.append(path)
    return inputs

def build_kernel(args):
    # CI可先创建空目录；无显式目录的直接调用也在临时工作目录外保留失败证据。
    directory=getattr(args,'audit_directory',None) or args.output.with_name(args.output.name+'.audit')
    audit_path=directory.resolve()
    output=args.output.resolve()
    roots=[getattr(args,name).resolve() for name in ('source','build','resources')]
    if audit_path==output or audit_path.is_relative_to(output) or output.is_relative_to(audit_path) or any(
            audit_path==root or audit_path.is_relative_to(root) or root.is_relative_to(audit_path) for root in roots):
        raise ValueError('audit-directory不得与输入树或候选输出重叠')
    audit=LinkAudit(directory)
    try:
        return _build_kernel(args,audit)
    except BaseException as error:
        # SIGKILL不执行这里；各长步骤前的原子阶段文件才是最低持久化保证。
        failed_phase=audit.value['phase']
        linkmap,map_failure=None,None
        try:
            linkmap=audit.capture_map()
        except (ValueError,OSError) as map_error:
            map_failure={'type':type(map_error).__name__,'message':str(map_error)[:4000]}
        try:
            audit.update('failed',complete=False,appleLinkVerified=False,
                         failure={'phase':failed_phase,'type':type(error).__name__,'message':str(error)[:4000]},
                         linkMap=linkmap,mapCaptureFailure=map_failure)
        except BaseException as export_error:
            try:
                print(json.dumps({'auditExportFailure':{'type':type(export_error).__name__,'message':str(export_error)[:4000]},
                                  'originalBuildFailure':{'type':type(error).__name__,'message':str(error)[:4000]}},ensure_ascii=False),file=sys.stderr)
            except BaseException:
                # 最后诊断管道也可能失败；仍由外层bare raise保留原native异常对象。
                pass
        raise


def _build_kernel(args,audit):
    require_apple_tools()
    source = args.source.resolve(strict=True)
    build = args.build.resolve(strict=True)
    resources = args.resources.resolve(strict=True)
    if args.output.exists():
        raise ValueError('output already exists; choose a new output directory')
    if run(['git', 'describe', '--tags', '--exact-match', 'HEAD'], source) != TAG:
        raise ValueError('source tag mismatch')
    commit = run(['git', 'rev-parse', 'HEAD'], source)
    if commit != COMMIT:
        raise ValueError('source commit does not match official pinned tag')
    policy = validate_offline_policy(source)
    compatibility = validate_build_compatibility(source)
    acceptance_only = getattr(args, 'acceptance_only', False)
    config = (build / 'config_host.mk').read_text()
    if 'iOS' not in config or 'arm64' not in config:
        raise ValueError('not a configured arm64 iOS LibreOffice build')
    make = gnu_make()
    validate_resource_layout(resources)
    kernel_sources=[file_identity(ROOT/relative,ROOT) for relative in
                    ('src/OfficePdfKernel.mm','src/OfficePdfRegistration.cxx','include/OfficePdfKernel.h',
                     'include/module.modulemap','ci/inspect_link.py')]
    audit.update('validated',sourceTag=TAG,sourceCommit=commit,offlinePolicy=policy,buildCompatibility=compatibility,
                 configHost=file_identity(build/'config_host.mk',build),kernelSourceFiles=kernel_sources)
    # 配置驱动官方全集，加固定版本审计补集；保留.a及NSS单独.o。
    with tempfile.TemporaryDirectory(prefix='office-pdf-ios-') as temporary:
        work = pathlib.Path(temporary)
        makefile = work / 'collect.mk'
        makefile.write_text(collector_makefile(), encoding='utf-8', newline='\n')
        actual_source = run([make['path'], '--no-print-directory', '-s', '-f', makefile, 'office_pdf_source_identity'], build)
        if pathlib.Path(actual_source).resolve() != source:
            raise ValueError('configured build source does not match pinned source')
        audit.update('rebuild')
        rebuilt = rebuild_patched_source(source, build, make, policy)
        if validate_build_compatibility(source) != compatibility:
            raise ValueError('重建期间构建兼容身份变化')
        actual_source = run([make['path'], '--no-print-directory', '-s', '-f', makefile, 'office_pdf_source_identity'], build)
        if pathlib.Path(actual_source).resolve() != source:
            raise ValueError('rebuilt source identity changed')
        profile=validate_link_profile(source,build)
        collector=work/'collector.txt'
        with collector.open('wb') as stream:
            subprocess.run([make['path'],'--no-print-directory','-s','-f',str(makefile),'office_pdf_static_inputs'],
                           cwd=build,stdout=stream,check=True)
        if collector.stat().st_size>1024**2:
            raise ValueError('原始collector输出超过1MiB')
        collector_text=collector.read_bytes().decode('utf-8')
        raw_inputs=link_inputs(collector_text,build)
        inputs = ios_link_inputs(collector_text, build)
        registrations = registration_inputs(build)
        resource_files = inventory(resources)
        audit.update('compile-shim',upstreamRebuild=rebuilt,profile=profile,
                     collector={'text':collector_text,'bytes':collector.stat().st_size,'sha256':sha256(collector),
                                'rawInputs':[str(p.relative_to(build)) for p in raw_inputs],
                                'supplementalInputs':[str(p.relative_to(build)) for p in inputs if p not in raw_inputs]},
                     nativeRegistration=registrations)
        for path in inputs:
            if run(['xcrun', 'lipo', '-archs', path]).split() != ['arm64']:
                raise ValueError('input is not exclusively arm64: ' + str(path))
        sdk = run(['xcrun', '--sdk', 'iphoneos', '--show-sdk-path'])
        obj = work / 'OfficePdfKernel.o'
        run(['xcrun', '--sdk', 'iphoneos', 'clang++', '-std=c++17', '-Oz', '-fobjc-arc', '-DIOS',
             '-DOFFICE_PDF_ACCEPTANCE_ONLY=' + ('1' if acceptance_only else '0'),
             '-DOFFICE_PDF_POLICY_SHA256="' + policy['policySha256'] + '"',
             '-target', 'arm64-apple-ios' + MIN_IOS, '-isysroot', sdk, '-I', source / 'include',
             '-I', ROOT / 'include', '-c', ROOT / 'src/OfficePdfKernel.mm', '-o', obj])
        registration_obj = work / 'OfficePdfRegistration.o'
        audit.update('compile-registration')
        run(['xcrun', '--sdk', 'iphoneos', 'clang++', '-std=c++17', '-Oz', '-DIOS', '-DDISABLE_DYNLOADING',
             '-target', 'arm64-apple-ios' + MIN_IOS, '-isysroot', sdk,
             '-I', build / 'config_host', '-I', build / 'include', '-I', source / 'include',
             '-I', build / 'workdir/CustomTarget/ios', '-c', ROOT / 'src/OfficePdfRegistration.cxx', '-o', registration_obj])
        # Apple nm只列定义的外部符号；C++改名或遗漏注册表必须在归档前失败。
        validate_registration_symbols(run(['xcrun', 'nm', '-gUj', registration_obj]))
        audit.update('scan-inputs')
        rows=scan_link_inputs([*inputs,obj,registration_obj],build)
        audit.update('normalize',referenceUniverseComplete=True,**compact_link_rows(rows))
        inputs,rules=normalize_ios_link_inputs(inputs,build,rows)
        all_selected=[*inputs,obj,registration_obj]
        # 公开C ABI和真实注册根都进入引用根，不能以“没有静态consumer”为由删除。
        public_roots=['_OfficePdfKernelProbeJSON','_OfficePdfKernelConvertJSON',
                      '_OfficePdfKernelAcceptanceConvertJSON','_OfficePdfKernelFreeString',
                      '_lo_get_factory_map','_lo_get_constructor_map']
        symbols=audit_input_graph(rows,all_selected,public_roots)
        contracts=validate_ios_families(rows,all_selected,build,resources)
        selected_rows=[row for row in rows if pathlib.Path(row['path']) in all_selected]
        identities=[{k:row[k] for k in ('path','bytes','sha256')} for row in rows]
        identities+=profile['files']+contracts['identityFiles']+kernel_sources
        identities+=[file_identity(build/entry['path'],build) for entry in registrations]
        unchanged_identities(identities)
        audit.update('aggregate',rules=rules,selectedInputIndices=[i for i,row in enumerate(rows) if pathlib.Path(row['path']) in all_selected],
                     symbols=symbols,contracts=contracts,publicRoots=public_roots,inputAuditComplete=True)
        archive = work / 'OfficePdfKernel'
        run(['xcrun', 'libtool', '-static', '-o', archive, obj, registration_obj, *inputs])
        aggregate=verify_aggregate(archive,selected_rows)
        unchanged_identities(identities)
        audit.update('aggregate-verified',aggregate=aggregate,aggregateAuditComplete=True)
        # 链接真实可执行探针，防止仅生成archive却有未满足的LO/C++/系统依赖。
        probe = work / 'probe.mm'
        probe.write_text('#include "OfficePdfKernel.h"\nint main(){auto p=OfficePdfKernelProbeJSON(0);OfficePdfKernelFreeString(p);return 0;}\n')
        executable = work / 'probe'
        # NSS Darwin默认使用系统SQLite；必须链接目标iPhoneOS SDK的sqlite3，
        # 不能凭主机检测结果查找一个不存在的libsqlite3.a或省略真实未定义符号。
        system_libraries = ('z', 'iconv', 'xml2', 'c++', 'sqlite3')
        framework_flags = []
        for name in ('Foundation', 'UIKit', 'CoreGraphics', 'CoreText', 'CoreFoundation',
                     'QuartzCore', 'Security', 'CFNetwork', 'SystemConfiguration', 'MobileCoreServices',
                     'ImageIO', 'Accelerate'):
            framework_flags += ['-framework', name]
        command=['xcrun', '--sdk', 'iphoneos', 'clang++', '-std=c++17', '-target', 'arm64-apple-ios' + MIN_IOS,
             '-isysroot', sdk, '-I', ROOT / 'include', probe, '-Wl,-force_load,' + str(archive),
             '-Wl,-map,'+str(audit.directory/'link-map.log'),
             *['-l' + name for name in system_libraries], *framework_flags, '-o', executable]
        audit.update('link',linkCommand=[str(p) for p in command],linkMapPlanned=True,
                     systemLibraries=list(system_libraries),frameworkFlags=framework_flags)
        run(command)
        platform = run(['xcrun', 'vtool', '-show-build', executable])
        if 'platform IOS' not in platform:
            raise ValueError('linked probe is not an iOS device executable')
        linkmap=audit.capture_map()
        if linkmap is None or not linkmap['bytes']:
            raise ValueError('真实链接未留下非空link-map.log')
        unchanged_identities(identities)
        if validate_offline_policy(source)!=policy or validate_build_compatibility(source)!=compatibility or inventory(resources)!=resource_files:
            raise ValueError('最终链接期间源策略/兼容或资源身份变化')
        audit.update('package',linkMap=linkmap,platform=platform,inputsUnchanged=True)
        args.output.mkdir(parents=True)
        framework = args.output / 'OfficePdfKernel.framework'
        (framework / 'Headers').mkdir(parents=True)
        (framework / 'Modules').mkdir()
        shutil.copy2(archive, framework / 'OfficePdfKernel')
        shutil.copy2(ROOT / 'include/OfficePdfKernel.h', framework / 'Headers')
        shutil.copy2(ROOT / 'include/module.modulemap', framework / 'Modules')
        import plistlib
        (framework / 'Info.plist').write_bytes(plistlib.dumps({'CFBundleIdentifier': 'com.lizhao.office-pdf.kernel',
            'CFBundleName': 'OfficePdfKernel', 'CFBundleExecutable': 'OfficePdfKernel', 'CFBundlePackageType': 'FMWK',
            'CFBundleVersion': '1', 'CFBundleShortVersionString': '1.0', 'MinimumOSVersion': MIN_IOS}))
        resource_manifest, final_data = package_compact_resources(
            resources, args.output, resource_files, commit, policy, compatibility)
        if any((entry['bytes'],entry['sha256'])!=(contracts['icu']['bytes'],contracts['icu']['sha256']) for entry in final_data):
            raise ValueError('ICU最终AppRootResources数据链不一致')
        shutil.copy2(executable, args.output / 'link-probe')
        xcode=run(['xcodebuild','-version'])
        unchanged_identities(identities)
        if audit.capture_map()!=linkmap:
            raise ValueError('打包期间link-map.log身份变化')
        audit.update('complete',complete=True,appleLinkVerified=True,finalICUResources=final_data,linkMap=linkmap)
        shutil.copy2(audit.directory/'AUDIT.json',args.output/'AUDIT.json')
        shutil.copy2(audit.directory/'link-map.log',args.output/'link-map.log')
        copied_map=args.output/'link-map.log'
        if copied_map.stat().st_size!=linkmap['bytes'] or sha256(copied_map)!=linkmap['sha256']:
            raise ValueError('候选link-map.log复制身份不一致')
        manifest = {'sourceTag': TAG, 'sourceCommit': commit, 'architecture': 'arm64', 'platform': 'iOS',
            'minimumIOS': MIN_IOS, 'offlinePolicy': policy, 'buildCompatibility': compatibility, 'acceptanceOnly': acceptance_only,
            'systemLibraries': list(system_libraries),
            'gnuMake': make, 'upstreamRebuild': rebuilt,
            'shimSourceSha256': sha256(ROOT / 'src/OfficePdfKernel.mm'),
            'registrationSourceSha256': sha256(ROOT / 'src/OfficePdfRegistration.cxx'),
            'nativeRegistration': registrations,
            'appleLinkVerified': True, 'deviceRuntimeVerified': False, 'strictOffline': False, 'available': False,
            'reason': 'IOS_OFFLINE_POLICY_UNQUALIFIED', 'layout': resource_manifest['layout'],
            'mainICU': resource_manifest['mainICU'], 'resources': resource_manifest['resources'],
            'inputs': [{'path': str(p.relative_to(build)), 'bytes': p.stat().st_size,
                        'sha256': sha256(p)} for p in inputs],
            'finalLinkAudit':{'path':'AUDIT.json','sha256':sha256(args.output/'AUDIT.json'),'linkMap':audit.value['linkMap']},
            'artifacts': inventory(args.output), 'xcode': xcode}
        (args.output / 'BUILD.json').write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    for flag in ('source', 'build', 'resources', 'output'):
        parser.add_argument('--' + flag, type=pathlib.Path, required=True)
    parser.add_argument('--acceptance-only', action='store_true',
                        help='仅启用独立原生验收C ABI；不解除生产入口门禁，不供业务基座使用')
    parser.add_argument('--audit-directory',type=pathlib.Path,
                        help='新空普通目录；长原生命令前原子保留AUDIT.json与真实link-map.log')
    args = parser.parse_args()
    try:
        build_kernel(args)
    except (ValueError, OSError, RuntimeError, subprocess.CalledProcessError) as error:
        parser.exit(1, '构建失败（未证明iOS可用）: ' + str(error) + '\n')

if __name__ == '__main__':
    main()

"""只传输成功 make 边界的公开构建树；缓存不承担资格或发布证明。"""
import hashlib
import decimal
import json
import os
import pathlib
import posixpath
import re
import shutil
import tarfile
import time

ROOTS = ('libreoffice-source', 'libreoffice-build')
PHASES = ('tools', 'vcl', 'sd', 'sw', 'final')
TARGETS = ('cross-toolset', 'vcl.allbuild', 'sd.allbuild', 'sw.allbuild', 'build')
MAX_CACHE_BYTES = 4 * 1024**3
CACHE_OVERHEAD_BYTES = 64 * 1024**2
MAX_EXPANDED_BYTES = 40 * 1024**3
MAX_MEMBERS = 500000
FORMAT = 'office-pdf-ios-checkpoint-v1'


def check_deadline(deadline):
    if deadline is not None and time.monotonic() >= deadline:
        raise RuntimeError('检查点达到本阶段内部时限')


def mtime_ns(item):
    try:
        value = decimal.Decimal(item.pax_headers.get('mtime', str(item.mtime))) * 1000000000
        if not value.is_finite() or value != value.to_integral_value() or abs(value) > 2**63-1:
            raise ValueError('归档 mtime 超限或不足纳秒精度')
        return int(value)
    except decimal.InvalidOperation as error:
        raise ValueError('归档 mtime 无效') from error


def predecessor(phase):
    if phase not in PHASES:
        raise ValueError('未知构建阶段')
    index = PHASES.index(phase)
    return PHASES[index-1] if index else None


def target(phase):
    predecessor(phase)
    return TARGETS[PHASES.index(phase)]


def sha256(path):
    value = hashlib.sha256()
    with path.open('rb') as stream:
        for chunk in iter(lambda: stream.read(1024*1024), b''):
            value.update(chunk)
    return value.hexdigest()


def cache_key(identity, phase):
    predecessor(phase)
    digest = hashlib.sha256(json.dumps(identity, sort_keys=True, separators=(',', ':')).encode()).hexdigest()
    return FORMAT + '-' + digest + '-' + phase


def clean_name(name, roots=ROOTS):
    if not isinstance(name, str) or not name or '\\' in name or ':' in name or '\x00' in name:
        raise ValueError('归档路径无效')
    path = pathlib.PurePosixPath(name)
    if path.is_absolute() or any(p in ('', '.', '..') for p in name.split('/')) or path.parts[0] not in roots:
        raise ValueError('归档路径逃逸')
    return path


def link_destination(name, link, work, roots=ROOTS):
    if not link or '\\' in link or '\x00' in link or ':' in link:
        raise ValueError('归档链接无效')
    if link.startswith('/'):
        prefix = work.as_posix().rstrip('/') + '/'
        if not link.startswith(prefix):
            raise ValueError('绝对链接逃逸')
        value = link[len(prefix):]
    else:
        value = posixpath.join(posixpath.dirname(name), link)
    value = posixpath.normpath(value)
    clean_name(value, roots)
    return value


def audit(payload, work, deadline=None, roots=ROOTS):
    """先完整审计，再由调用者解包；不调用 extract/extractall。"""
    members = {}
    aliases = set()
    expanded = 0
    with tarfile.open(payload, 'r:gz') as archive:
        for item in archive:
            check_deadline(deadline)
            clean_name(item.name, roots)
            alias = item.name.casefold()
            if alias in aliases or len(members) >= MAX_MEMBERS:
                raise ValueError('归档重复路径或条目超限')
            aliases.add(alias)
            if not (item.isdir() or item.isfile() or item.issym()):
                raise ValueError('拒绝硬链接、特殊文件或未知 tar 类型')
            if item.mode & ~0o777 or item.size < 0:
                raise ValueError('归档权限或长度无效')
            mtime_ns(item)
            if item.isfile():
                expanded += item.size
                if expanded > MAX_EXPANDED_BYTES:
                    raise ValueError('归档展开体积超限')
            members[item.name] = item
    # 任何文件或链接都不能成为其他归档项的写入祖先。
    for name, item in members.items():
        for parent in pathlib.PurePosixPath(name).parents:
            ancestor = members.get(parent.as_posix())
            if ancestor and not ancestor.isdir():
                raise ValueError('归档非目录祖先')
        if item.issym():
            current = link_destination(name, item.linkname, work, roots)
            visited = {name}
            for _ in range(100):
                parts = pathlib.PurePosixPath(current).parts
                replacement = None
                for index in range(1, len(parts)+1):
                    part = '/'.join(parts[:index])
                    entry = members.get(part)
                    if entry and entry.issym():
                        if part in visited:
                            raise ValueError('归档链接环')
                        visited.add(part)
                        replacement = posixpath.normpath(posixpath.join(
                            link_destination(part, entry.linkname, work, roots), *parts[index:]))
                        clean_name(replacement, roots)
                        break
                if replacement is None:
                    break
                current = replacement
            else:
                raise ValueError('归档链接链超限')
    if any(name not in members or not members[name].isdir() for name in roots):
        raise ValueError('归档缺少精确允许根')
    return members, expanded


def config_identity(work):
    root = work / ROOTS[1]
    return {p.relative_to(root).as_posix(): sha256(p) for p in sorted(root.glob('config*.mk')) if p.is_file() and not p.is_symlink()}


def save(work, output, identity, phase, deadline=None):
    predecessor(phase)
    if phase == 'final':
        raise ValueError('final 不保存续编检查点')
    return _save(work, output, identity, phase, deadline, ROOTS, 'build')


def save_candidate(candidate, output, identity, deadline=None):
    if candidate.name != 'candidate' or candidate.is_symlink() or not candidate.is_dir():
        raise ValueError('最终候选目录无效')
    if not any(candidate.iterdir()):
        raise ValueError('最终候选为空')
    return _save(candidate.parent, output, identity, 'final', deadline, ('candidate',), 'candidate')


def _save(work, output, identity, phase, deadline, roots, kind):
    if output.exists() or output.is_symlink():
        raise ValueError('拒绝覆盖检查点目录')
    started = time.monotonic()
    work = work.resolve(strict=True)
    output.mkdir()
    payload = output / 'payload.tar.gz'
    with tarfile.open(payload, 'w:gz', format=tarfile.PAX_FORMAT, compresslevel=6) as archive:
        for name in roots:
            root = work / name
            if not root.is_dir() or root.is_symlink():
                raise ValueError('检查点构建根无效')
            for path in (root, *sorted(root.rglob('*'))):
                check_deadline(deadline)
                relative = path.relative_to(work).as_posix()
                clean_name(relative, roots)
                archive.inodes.clear()  # 硬链接按独立文件保真，恢复不接受 tar 硬链接。
                item = archive.gettarinfo(str(path), relative)
                # PAX 标准 mtime 保留原始纳秒，避免跨 job 浮点舍入破坏 make 的增量关系。
                original_ns = path.lstat().st_mtime_ns
                seconds, nanos = divmod(abs(original_ns), 1000000000)
                item.pax_headers['mtime'] = ('-' if original_ns < 0 else '') + str(seconds) + '.' + f'{nanos:09d}'
                item.uid = item.gid = 0
                item.uname = item.gname = ''
                if item.isfile():
                    with path.open('rb') as stream:
                        archive.addfile(item, stream)
                else:
                    archive.addfile(item)
                if payload.stat().st_size + CACHE_OVERHEAD_BYTES > MAX_CACHE_BYTES:
                    raise ValueError('检查点超出 4GiB 免费传输预算')
    members, expanded = audit(payload, work, deadline, roots)
    manifest = {'format': FORMAT, 'kind': kind, 'archiveRoots': list(roots), 'identity': identity, 'phase': phase, 'target': target(phase),
                'payloadSha256': sha256(payload), 'payloadBytes': payload.stat().st_size,
                'expandedBytes': expanded, 'members': len(members), 'config': config_identity(work) if kind == 'build' else {}}
    manifest_path = output / 'manifest.json'
    manifest_path.write_text(json.dumps(manifest, ensure_ascii=False, sort_keys=True, indent=2)+'\n', encoding='utf-8')
    total = payload.stat().st_size + manifest_path.stat().st_size + CACHE_OVERHEAD_BYTES
    if total > MAX_CACHE_BYTES:
        raise ValueError('检查点及开销超出 4GiB 免费传输预算')
    check_deadline(deadline)
    return {**manifest, 'cacheKey': cache_key(identity, phase), 'manifestSha256': sha256(manifest_path),
            'accountedCacheBytes': total, 'seconds': time.monotonic()-started}


def restore(work, directory, identity, phase, expected_payload, expected_manifest, deadline=None):
    previous = predecessor(phase)
    if previous is None:
        raise ValueError('初始阶段禁止恢复检查点')
    started = time.monotonic()
    payload = directory / 'payload.tar.gz'
    manifest_path = directory / 'manifest.json'
    if directory.is_symlink() or not directory.is_dir() or {p.name for p in directory.iterdir()} != {'payload.tar.gz', 'manifest.json'}:
        raise ValueError('缓存缺失或结构无效')
    for path in (payload, manifest_path):
        if path.is_symlink() or not path.is_file():
            raise ValueError('检查点文件无效')
    if payload.stat().st_size + manifest_path.stat().st_size + CACHE_OVERHEAD_BYTES > MAX_CACHE_BYTES or manifest_path.stat().st_size > 65536:
        raise ValueError('检查点体积超限')
    if not re.fullmatch('[a-f0-9]{64}', expected_payload) or not re.fullmatch('[a-f0-9]{64}', expected_manifest):
        raise ValueError('缺少前 job 受信 SHA')
    if sha256(payload) != expected_payload or sha256(manifest_path) != expected_manifest:
        raise ValueError('检查点 SHA 不符')
    manifest = json.loads(manifest_path.read_text(encoding='utf-8'))
    if not isinstance(manifest, dict) or manifest.get('format') != FORMAT or manifest.get('kind') != 'build' or manifest.get('archiveRoots') != list(ROOTS) or manifest.get('identity') != identity or manifest.get('phase') != previous or manifest.get('target') != target(previous):
        raise ValueError('检查点身份或阶段顺序不符')
    work = work.resolve(strict=True)
    for name in ROOTS:
        if (work / name).exists() or (work / name).is_symlink():
            raise ValueError('拒绝覆盖恢复根')
    members, expanded = audit(payload, work, deadline)
    if manifest.get('payloadSha256') != expected_payload or manifest.get('payloadBytes') != payload.stat().st_size or manifest.get('expandedBytes') != expanded or manifest.get('members') != len(members):
        raise ValueError('检查点清单与归档不符')
    if shutil.disk_usage(work).free < expanded + 1024**3:
        raise ValueError('恢复磁盘不足，禁止清理其他文件')
    # 审计完成后占有两个新根，再写普通文件。仅最后创建 symlink。
    for name in ROOTS:
        (work/name).mkdir()
    with tarfile.open(payload, 'r:gz') as archive:
        for item in members.values():
            check_deadline(deadline)
            path = work / item.name
            path.parent.mkdir(parents=True, exist_ok=True)
            if item.isdir():
                path.mkdir(exist_ok=True)
            elif item.isfile():
                with archive.extractfile(item) as source, path.open('xb') as destination:
                    shutil.copyfileobj(source, destination, 1024*1024)
                path.chmod(item.mode)
                os.utime(path, ns=(mtime_ns(item), mtime_ns(item)))
        for item in members.values():
            if item.issym():
                path = work / item.name
                path.symlink_to(item.linkname)
                if os.utime in os.supports_follow_symlinks:
                    os.utime(path, ns=(mtime_ns(item), mtime_ns(item)), follow_symlinks=False)
        for item in sorted(members.values(), key=lambda p: p.name.count('/'), reverse=True):
            if item.isdir():
                path = work / item.name
                path.chmod(item.mode)
                os.utime(path, ns=(mtime_ns(item), mtime_ns(item)))
    if config_identity(work) != manifest.get('config'):
        raise ValueError('恢复配置 SHA 不符')
    check_deadline(deadline)
    return {'restored': True, 'phase': previous, 'expandedBytes': expanded,
            'members': len(members), 'seconds': time.monotonic()-started}

#!/usr/bin/env python3
"""仅作用于本次构建树的可追溯Oz委派；不修改上游文件或BUILD编译配置。"""
import argparse
import base64
import contextlib
import hashlib
import json
import math
import os
import pathlib
import re
import shlex
import shutil
import stat
import struct
import subprocess
import sys
import time

sys.dont_write_bytecode = True
FORMAT = 'office-pdf-ios-compact-profile-v1'
SOURCE_FILES = ('solenv/gbuild/platform/iOS.mk', 'solenv/gbuild/platform/iOS_AARCH64_GCC.mk',
                'solenv/gbuild/platform/com_GCC_defs.mk', 'solenv/gbuild/platform/com_GCC_class.mk')
TRACE_MAX_BYTES = 128 * 1024**2
TRACE_RECORD_BYTES = 128 * 1024
TRACE_MAX_RECORDS = 50000
STATE_METADATA_RESERVE = 8 * 1024**2
MAX_COMPILERS = 16
REJECTION_RECORD_BYTES = 64 * 1024
CONFIG_MAX_BYTES = 4 * 1024**2
MODULE = pathlib.Path(__file__).resolve()


def encoded(value):
    return (json.dumps(value, sort_keys=True, ensure_ascii=False, separators=(',', ':'))+'\n').encode('utf-8')


def regular(path):
    path = pathlib.Path(path)
    for parent in (path, *path.parents):
        info = parent.lstat()
        if stat.S_ISLNK(info.st_mode) or getattr(info, 'st_file_attributes', 0) & 0x400:
            raise ValueError('profile路径包含链接：'+str(parent))
    info = path.lstat()
    if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
        raise ValueError('profile需要单链接普通文件：'+str(path))
    return info


def stat_key(info):
    # Windows lstat按.exe后缀补执行位而fstat不补；POSIX仍比较完整mode。
    mode = stat.S_IFMT(info.st_mode) if os.name == 'nt' else info.st_mode
    return (info.st_dev, info.st_ino, mode, info.st_nlink, info.st_size, info.st_mtime_ns, info.st_ctime_ns)


def read_stable(path, limit=None, object_file=False):
    path = pathlib.Path(path)
    before = regular(path)
    if limit is not None and before.st_size > limit:
        raise ValueError('profile文件超过预算')
    fd = os.open(path, os.O_RDONLY | getattr(os, 'O_NOFOLLOW', 0) | getattr(os, 'O_NONBLOCK', 0))
    with os.fdopen(fd, 'rb') as stream:
        if stat_key(os.fstat(stream.fileno())) != stat_key(before):
            raise ValueError('profile打开时身份变化')
        digest = hashlib.sha256(); data = bytearray(); total = 0
        for chunk in iter(lambda: stream.read(1024*1024), b''):
            total += len(chunk)
            if limit is not None and total > limit:
                raise ValueError('profile读取超过预算')
            digest.update(chunk)
            if not object_file or len(data) < 32: data.extend(chunk if not object_file else chunk[:32-len(data)])
        if stat_key(os.fstat(stream.fileno())) != stat_key(before) or stat_key(regular(path)) != stat_key(before):
            raise ValueError('profile读取时身份变化')
    if object_file:
        if len(data) < 32 or struct.unpack('<I', data[:4])[0] != 0xfeedfacf or \
                struct.unpack('<I',data[4:8])[0] != 0x100000c or struct.unpack('<I',data[12:16])[0] != 1:
            raise ValueError('目标编译输出不是普通arm64 Mach-O MH_OBJECT（禁止bitcode/LTO）')
    return bytes(data), {'bytes':total,'sha256':digest.hexdigest()}


def identity(path):
    return read_stable(path, CONFIG_MAX_BYTES)[1]


def load(path, limit=CONFIG_MAX_BYTES):
    raw, _ = read_stable(path, limit)
    return decode_json(raw)


def decode_json(raw):
    def pairs(items):
        value = {}
        for key, item in items:
            if key in value: raise ValueError('profile JSON重复字段')
            value[key] = item
        return value
    return json.loads(raw.decode('utf-8'), object_pairs_hook=pairs,
                      parse_constant=lambda value: (_ for _ in ()).throw(ValueError('profile非法JSON数字')))


def write_new(path, value):
    with pathlib.Path(path).open('xb') as stream: stream.write(encoded(value))


def replace_json(path, value):
    temporary = path.with_name(path.name+'.'+str(os.getpid())+'.tmp')
    write_new(temporary,value)
    os.replace(temporary,path)


def profile_descriptor():
    module = identity(MODULE)
    return {'format':FORMAT,'profileId':'office-pdf-ios-compact-oz-v1','moduleSha256':module['sha256'],
            'module':module,'target':'arm64-apple-ios-device',
            'replacement':['-O2','-O3','-Os'],'effectiveOptimization':'-Oz',
            'explicitLowPreserved':['-O0','-O1','-Og'],'lto':False,'bitcode':False,'precompiledHeaders':False,
            'hostPolicy':'explicit-macos-pass-through; BUILD-config-unchanged',
            'unknownTargetPolicy':'reject','responseFiles':'reject-before-exec',
            'rejectionPolicy':'first-rejection-latch-fatal-even-if-configure-ignores-exit',
            'driverTransport':'canonical-base64-utf8-single-word; original-command-restored-without-shell-eval',
            'allowedNooptPreprocessorLiteral':'-Wp,-U_FORTIFY_SOURCE only with effective -O0',
            'temporaryDirectoryPolicy':'host-config-bound-build-tree; BUILD-config-unchanged',
            'traceBudget':{'bytes':TRACE_MAX_BYTES,'metadataReserveBytes':STATE_METADATA_RESERVE,
                           'recordBytes':TRACE_RECORD_BYTES,'records':TRACE_MAX_RECORDS,'compilerIdentities':MAX_COMPILERS},
            'coverage':'observed-delegated-compilations-only; not-100-percent-coverage'}


def make_immediate_literal(value):
    # Make的:=仍会展开美元符号并处理注释；单引号不能保护这两个边界。
    if not isinstance(value,str) or not value or value!=value.strip() or any(char in value for char in ('\x00','\r','\n','\\')):
        raise ValueError('临时目录不适合Make立即值')
    return value.replace('$','$$').replace('#','\\#')


def prepare_after_configure(source, build):
    source, build = pathlib.Path(source).resolve(), pathlib.Path(build).resolve()
    state = build/'.compact-profile'
    if state.exists() or state.is_symlink(): raise ValueError('profile已安装或存在陌生目录，拒绝重新配置')
    original, original_id = read_stable(build/'config_host.mk',CONFIG_MAX_BYTES)
    if b'compact_original_' in original: raise ValueError('config_host已含委派')
    pch=re.findall(r'^[ \t]*(?:export[ \t]+)?ENABLE_PCH[ \t]*(?::=|=)[ \t]*([^#\r\n]*)',original.decode('utf-8'),re.MULTILINE)
    if any(value.strip() for value in pch): raise ValueError('compact普通对象profile禁止PCH')
    build_id = identity(build/'config_build.mk')
    source_ids = {name:identity(source/name) for name in SOURCE_FILES}
    temporary = prepare_probe_tmp(build)
    temporary_value = make_immediate_literal(temporary.as_posix())
    state.mkdir(); (state/'trace').mkdir()
    (state/'config_host.original.mk').write_bytes(original)
    # :=在include边界立即捕获原命令，避免递归CC；外部BUILD配置不引入本片段。
    # configure通过$CC/$CXX展开命令时不会重新解释值内的shell引号。
    # 在Make直接执行的编码步骤保留原命令，再用无空白单参数传输；真实编译仍不经eval。
    prefix = ' '.join(shlex.quote(item) for item in
                      (pathlib.Path(sys.executable).as_posix(),'-B',MODULE.as_posix(),'--build',build.as_posix()))
    # 上游config_host会重新export配置期TMP/TMPDIR，覆盖Runner环境；绑定同一受审计host配置，
    # 让递归make、collector及最终直接gbuild重建都继承构建树内临时根，BUILD配置保持原字节。
    # GNU Make 3.81不能叠加override/export；拆分指令才能真实覆盖并导出给子进程。
    lines = ['\n# '+FORMAT, 'override TMP := '+temporary_value, 'override TMPDIR := '+temporary_value,
             'export TMP TMPDIR',
             'compact_original_CC := $(CC)', 'compact_original_CXX := $(CXX)']
    for name in ('CC','CXX'):
        captured = "'$(subst ','\"'\"',$(compact_original_"+name+"))'"
        lines.append('compact_encoded_'+name+' := $(shell '+prefix+' --encode-driver '+captured+')')
        lines.append('override '+name+' := '+prefix+' --driver-base64 $(compact_encoded_'+name+') --')
    wrapped = original + ('\n'.join(lines)+'\n').encode('utf-8')
    (build/'config_host.mk').write_bytes(wrapped)
    receipt = {'format':FORMAT,'source':str(source),'build':str(build),'descriptor':profile_descriptor(),
               'sources':source_ids,'originalHost':original_id,'configBuild':build_id,
               'configHost':identity(build/'config_host.mk'),'probeTemporaryRoot':str(temporary),
               'python':str(pathlib.Path(sys.executable).resolve())}
    write_new(state/'receipt.json',receipt)
    write_new(state/'ledger.json',{'count':0,'bytes':0,'pending':[]})
    return verify_prepared(source,build)


def verify_prepared(source, build):
    source, build = pathlib.Path(source).resolve(), pathlib.Path(build).resolve()
    state = build/'.compact-profile'; receipt = load(state/'receipt.json')
    if receipt.get('format') != FORMAT or receipt.get('source') != str(source) or receipt.get('build') != str(build) \
            or receipt.get('descriptor') != profile_descriptor():
        raise ValueError('profile源/配置/模块身份不符')
    for path, expected in ((build/'config_host.mk',receipt['configHost']),
                           (build/'config_build.mk',receipt['configBuild']),
                           (state/'config_host.original.mk',receipt['originalHost'])):
        if identity(path) != expected: raise ValueError('profile配置身份变化：'+str(path))
    if set(receipt['sources']) != set(SOURCE_FILES): raise ValueError('profile原始源码集合变化')
    for name, expected in receipt['sources'].items():
        if identity(source/name) != expected: raise ValueError('profile上游原件变化：'+name)
    if receipt.get('probeTemporaryRoot') != str(build/'.compact-probe-tmp'):
        raise ValueError('profile临时目录绑定变化')
    prepare_probe_tmp(build)
    # 跨Mac job允许inode不同，但必须先全文SHA等同，才能建立本job的7stat基线。
    for path in sorted(state.glob('compiler-*.json')):
        compiler=load(path)
        if compiler.get('job') != os.environ.get('GITHUB_JOB',''):
            with locked(state):
                compiler=load(path)
                if compiler.get('job') != os.environ.get('GITHUB_JOB',''):
                    actual,fingerprint=compiler_identity_unlocked(pathlib.Path(compiler['path']))
                    if actual != compiler['identity']: raise ValueError('续阶段真实编译器SHA变化')
                    compiler.update(stat=fingerprint,job=os.environ.get('GITHUB_JOB',''))
                    replace_json(path,compiler)
    return receipt


def option_values(args, names):
    values = []
    for index, arg in enumerate(args):
        if names==('-o',) and arg.startswith('-o') and arg!='-o' and not arg.startswith(('-objc','-object-')):
            if arg.startswith('-o='): raise ValueError('不接受歧义-o=输出写法')
            values.append(arg[2:]); continue
        if arg in names:
            if index+1 == len(args): raise ValueError('目标选项缺值')
            values.append(args[index+1])
        for name in names:
            if arg.startswith(name+'='): values.append(arg[len(name)+1:])
    return values


def rewrite_arguments(driver, args):
    all_args = [*driver[1:],*args]
    if any(not isinstance(arg,str) or '\x00' in arg or '\n' in arg for arg in [*driver,*args]):
        raise ValueError('编译argv无效')
    if len(encoded([driver,args])) > TRACE_RECORD_BYTES//3: raise ValueError('编译argv超过单记录预算')
    if any(arg.startswith('@') for arg in all_args): raise ValueError('本profile不支持响应文件，拒绝未审计展开')
    opts = [arg for arg in all_args if re.fullmatch(r'-O.*',arg)]
    effective = opts[-1] if opts else None
    # 固定上游com_GCC_defs.mk的NOOPT字面量仅取消FORTIFY宏；不开放任意-Wp转发。
    if any(arg.startswith('-Wp,') and not (arg=='-Wp,-U_FORTIFY_SOURCE' and effective=='-O0') for arg in all_args):
        raise ValueError('拒绝未知预处理器间接参数')
    if '--' in all_args or any(arg.startswith(('-flto','-fembed-bitcode','-foffload-lto','-Xclang','-Xarch_',
                                              '-mllvm','-Wclang,','-mios-simulator-version-min')) for arg in all_args):
        raise ValueError('拒绝LTO/bitcode或间接编译参数')
    triples = option_values(all_args,('-target','--target'))
    arches = option_values(all_args,('-arch',))
    sdks = option_values(all_args,('-isysroot','--sysroot'))
    if len(set(triples)) > 1 or len(set(arches)) > 1 or len(set(sdks)) > 1:
        raise ValueError('目标选项冲突')
    triple, arch, sdk = (values[-1] if values else '' for values in (triples,arches,sdks))
    ios_triple = bool(re.fullmatch(r'arm64-apple-ios[0-9.]*',triple))
    ios_sdk = bool(re.search(r'/iPhoneOS[^/]*\.sdk/?$',sdk,re.I))
    host_triple = bool(re.fullmatch(r'(?:arm64|x86_64)-apple-(?:macosx?|darwin)[0-9.]*',triple))
    host_sdk = bool(re.search(r'/MacOSX[^/]*\.sdk/?$',sdk,re.I))
    if (ios_triple or (arch == 'arm64' and ios_sdk)) and (not sdk or ios_sdk) and (not triple or ios_triple) and (not arch or arch == 'arm64'):
        classification = 'target'
    elif (host_triple or host_sdk) and (not sdk or host_sdk) and (not triple or host_triple): classification = 'host'
    elif '--print-search-dirs' in all_args or (not any(arg in all_args for arg in ('-c','-E','-S','-fsyntax-only')) and \
            any(arg in ('--version','-version','-v','-V','-qversion','-dumpmachine','-dumpversion') or arg.startswith(('-print-prog-name=','-print-file-name=')) for arg in all_args)):
        classification = 'probe'
    else: raise ValueError('未知或不安全编译目标，不能标为Oz')
    if any(arg not in ('-O','-O0','-O1','-O2','-O3','-Os','-Oz','-Og') for arg in opts): raise ValueError('未知优化等级')
    # Meson会在已有-c/-o选项后追加此查询；Clang只打印搜索目录，不产生对象。
    compilation = '-c' in all_args and '--print-search-dirs' not in all_args and not any(arg in all_args for arg in ('-E','-S','-fsyntax-only'))
    after = list(args); optimization = 'unchanged'
    if classification == 'target' and compilation:
        if effective in ('-O0','-O1','-Og'): optimization = 'explicit-low'
        elif effective in ('-O2','-O3','-Os','-Oz'):
            after.append('-Oz'); optimization = 'Oz'
        else: optimization = 'unspecified-preserved'
    return after, {'classification':classification,'optimization':optimization,'originalEffectiveOptimization':effective,
                   'compilation':compilation,'target':{'triple':triple,'arch':arch,'sdk':sdk}}


@contextlib.contextmanager
def locked(state):
    lock = state/'lock'; deadline = time.monotonic()+60
    while True:
        try: lock.mkdir(); break
        except FileExistsError:
            if lock.is_symlink() or time.monotonic() >= deadline: raise ValueError('trace锁未释放，拒绝不完整证据')
            time.sleep(.02)
    try: yield
    finally: lock.rmdir()


def read_ledger(state):
    ledger=load(state/'ledger.json')
    if not isinstance(ledger,dict) or set(ledger)!= {'count','bytes','pending'} or \
            any(type(ledger[key]) is not int or ledger[key]<0 for key in ('count','bytes')) or \
            ledger['count']>TRACE_MAX_RECORDS or ledger['bytes']>TRACE_MAX_BYTES or \
            not isinstance(ledger['pending'],list) or \
            any(type(number) is not int or not 1<=number<=ledger['count'] for number in ledger['pending']) or \
            len(set(ledger['pending']))!=len(ledger['pending']):
        raise ValueError('trace账本结构/数字/预算非法')
    return ledger


def reserve_record(state):
    with locked(state):
        ledger = read_ledger(state)
        if ledger['count'] >= TRACE_MAX_RECORDS or ledger['bytes']+(len(ledger['pending'])+1)*TRACE_RECORD_BYTES+STATE_METADATA_RESERVE > TRACE_MAX_BYTES:
            raise ValueError('trace预算不足，编译前拒绝')
        number = ledger['count']+1; ledger['count']=number; ledger['pending'].append(number)
        replace_json(state/'ledger.json',ledger)
        return number


def finish_record(state, number, record):
    raw = encoded(record)
    if len(raw) > TRACE_RECORD_BYTES: raise ValueError('编译trace记录超限')
    with locked(state):
        ledger = read_ledger(state)
        if number not in ledger['pending']: raise ValueError('trace预留身份丢失')
        path = state/'trace'/f'{number:08d}.json'
        with path.open('xb') as stream: stream.write(raw)
        ledger['pending'].remove(number); ledger['bytes'] += len(raw)
        replace_json(state/'ledger.json',ledger)


def compiler_identity(state, executable):
    # Clang可达数百MiB；同一工具链稳定stat只哈希一次，避免每个对象重复扫描。
    fingerprint = list(stat_key(regular(executable)))
    key = hashlib.sha256(str(executable).encode()).hexdigest()
    path = state/('compiler-'+key+'.json')
    with locked(state):
        if path.exists():
            record = load(path)
            if record['path'] != str(executable) or record['stat'] != fingerprint:
                raise ValueError('编译器身份变化')
            return record['identity'],fingerprint
        if len(list(state.glob('compiler-*.json'))) >= MAX_COMPILERS:
            raise ValueError('真实编译器身份数量超过profile预算')
        # 仅流式哈希编译器，不把可执行文件整体装入内存。
        result, fingerprint = compiler_identity_unlocked(executable)
        replace_json(path,{'path':str(executable),'stat':fingerprint,'identity':result,'job':os.environ.get('GITHUB_JOB','')})
        return result,fingerprint


def compiler_identity_unlocked(executable):
    digest=hashlib.sha256(); before=regular(executable)
    fd=os.open(executable,os.O_RDONLY|getattr(os,'O_NOFOLLOW',0)|getattr(os,'O_NONBLOCK',0))
    with os.fdopen(fd,'rb') as stream:
        if stat_key(os.fstat(stream.fileno())) != stat_key(before): raise ValueError('编译器打开身份变化')
        for chunk in iter(lambda:stream.read(1024*1024),b''): digest.update(chunk)
        if stat_key(os.fstat(stream.fileno())) != stat_key(before) or stat_key(regular(executable)) != stat_key(before):
            raise ValueError('编译器哈希时变化')
    return {'bytes':before.st_size,'sha256':digest.hexdigest()},list(stat_key(before))


CONFIGURE_PROBE_NAMES = ('conftest.c','conftest.cc','conftest.cpp','conftest.cxx','conftest.m','conftest.mm','conftest.rc')
MESON_PROBE_NAMES = ('testfile.c','testfile.cc','testfile.cpp','testfile.cxx','testfile.m','testfile.mm')
MESON_BUILD = pathlib.PurePosixPath('workdir/UnpackedTarball/harfbuzz/builddir')
MESON_LOG = MESON_BUILD/'meson-logs/meson-log.txt'
PROBE_TMP = '.compact-probe-tmp'


def prepare_probe_tmp(build):
    """只给本轮make提供构建树内临时根；不修改全局环境或接受目录链接。"""
    build=pathlib.Path(build).absolute()
    if '..' in build.parts: raise ValueError('临时探测构建目录含父路径')
    # /var等位于工作根之前的系统别名允许；构建根和新临时根本身不能解析链接。
    build=build.parent.resolve(strict=True)/build.name
    def ordinary_directory(path, create=False):
        try: info=path.lstat()
        except FileNotFoundError:
            if not create: raise ValueError('临时探测父目录不存在') from None
            try: path.mkdir(mode=0o700)
            except FileExistsError: pass
            info=path.lstat()
        if stat.S_ISLNK(info.st_mode) or not stat.S_ISDIR(info.st_mode) or getattr(info,'st_file_attributes',0)&0x400:
            raise ValueError('临时探测目录不是安全普通目录')
    for parent in build.parents: ordinary_directory(parent)
    ordinary_directory(build,True)
    temporary=build/PROBE_TMP
    ordinary_directory(temporary,True)
    return temporary


def meson_probe_layout(source, log):
    """只承认本轮HarfBuzz的Meson日志及两个受控临时目录布局。"""
    return source.name in MESON_PROBE_NAMES and log == MESON_LOG and \
        source.parent.parent in (pathlib.PurePosixPath(PROBE_TMP),MESON_BUILD/'meson-private') and \
        re.fullmatch(r'tmp[A-Za-z0-9_-]{1,124}',source.parent.name) is not None


def controlled_configure_probe(build, args):
    """记录真实Autoconf/Meson探测身份；缺证明时继续按普通编译严格处理。"""
    cwd=pathlib.Path.cwd().resolve()
    try: cwd.relative_to(build)
    except ValueError: return None
    inputs=[arg for arg in args if not arg.startswith('-') and re.search(r'\.(?:c|cc|cpp|cxx|m|mm|rc)$',arg)]
    if len(inputs)!=1: return None
    source=pathlib.Path(inputs[0])
    source=source if source.is_absolute() else cwd/source
    if '..' in source.parts or source.parent!=cwd: return None
    relative=pathlib.PurePosixPath(source.relative_to(build).as_posix())
    autoconf=source.name in CONFIGURE_PROBE_NAMES
    if autoconf: log=cwd/'config.log';names=('conftest.o','conftest','a.out')
    elif meson_probe_layout(relative,MESON_LOG): log=build/pathlib.Path(str(MESON_LOG));names=('output.obj','output.exe')
    else: return None
    outputs=option_values(args,('-o',))
    if len(outputs)>1: return None
    if outputs:
        output=pathlib.Path(outputs[0]); output=output if output.is_absolute() else cwd/output
        if '..' in output.parts or output.parent!=cwd or output.name not in names: return None
    # 源、日志和输出都使用普通对象同一目录保护，不能通过探测身份绕过链接检查。
    target_output_path(build,['-o',str(source)])
    raw,source_id=read_stable(source,1024**2)
    if not log.exists(): return None
    target_output_path(build,['-o',str(log)])
    regular(log)
    fd=os.open(log,os.O_RDONLY|getattr(os,'O_NOFOLLOW',0)|getattr(os,'O_NONBLOCK',0))
    with os.fdopen(fd,'rb') as stream:
        header=stream.read(16384)
    if autoconf:
        if b'configure' not in header.lower(): return None
    else:
        harfbuzz=build/'workdir/UnpackedTarball/harfbuzz'
        lines=header.splitlines()
        required=(b'The Meson build system',('Source dir: '+str(harfbuzz)).encode('utf-8'),
                  ('Build dir: '+str(harfbuzz/'builddir')).encode('utf-8'))
        if not all(marker in lines for marker in required) or \
                not any(line.startswith(b'Build started at ') for line in lines) or \
                not any(line.startswith(b'Main binary: ') for line in lines): return None
    return {'source':source.relative_to(build).as_posix(),**source_id,
            'configLog':log.relative_to(build).as_posix(),'configLogHeaderSha256':hashlib.sha256(header).hexdigest()}


def target_output_path(build, args, probe=None):
    outputs=option_values(args,('-o',))
    if not outputs:
        inputs=[probe['source']] if probe is not None else \
            [arg for arg in args if not arg.startswith('-') and re.search(r'\.(?:c|cc|cpp|cxx|m|mm|s|S)$',arg)]
        if len(inputs)!=1: raise ValueError('目标编译无法推导唯一默认对象输出')
        outputs=[pathlib.Path(inputs[0]).stem+'.o']
    if len(outputs)!=1 or not outputs[0]: raise ValueError('目标编译缺少唯一输出路径')
    output=pathlib.Path(outputs[0]).absolute()
    if '..' in output.parts: raise ValueError('目标编译输出包含父路径')
    try: output.relative_to(build)
    except ValueError: raise ValueError('目标编译输出逃逸构建树') from None
    for parent in (output.parent,*output.parent.parents):
        info=parent.lstat()
        if stat.S_ISLNK(info.st_mode) or not stat.S_ISDIR(info.st_mode) or getattr(info,'st_file_attributes',0)&0x400:
            raise ValueError('目标编译输出父目录不安全')
    if output.exists() or output.is_symlink(): regular(output)
    return output


def rejection_latch(state, argv, error, receipt, context, started, code=125):
    """单独使用元数据预留，首个O_EXCL写者获胜；零字节/半写标记也永久阻止汇总。"""
    digest=hashlib.sha256(); length=0
    serializer=json.JSONEncoder(ensure_ascii=True,sort_keys=True,separators=(',',':'))
    for part in serializer.iterencode(argv):
        raw=part.encode('ascii'); length+=len(raw); digest.update(raw)
    complete=length<=REJECTION_RECORD_BYTES//2
    value={'format':FORMAT,'decision':{'rejected':True,'reason':str(error)[:2048]},
           'executed':context['executed'],'exitCode':code,'nativeExitCode':context['nativeExitCode'],
           'elapsedSeconds':time.monotonic()-started,'module':receipt['descriptor']['module'],
           'argv':argv if complete else None,
           'originalArgv':{'encoding':'json-ascii-original-argv-v1','bytes':length,'sha256':digest.hexdigest(),
                           'complete':complete,'omissionReason':None if complete else 'original argv exceeds bounded rejection record; exact encoded bytes/SHA retained'}}
    raw=(json.dumps(value,ensure_ascii=True,sort_keys=True,separators=(',',':'))+'\n').encode('ascii')
    if len(raw)>REJECTION_RECORD_BYTES: raise ValueError('拒绝回执超出元数据保留预算')
    path=state/'REJECTED.json'
    try:
        fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL|getattr(os,'O_NOFOLLOW',0),0o600)
    except FileExistsError:
        return  # 首拒绝不被后来的错误或并发进程替换；collect按存在即fatal处理。
    with os.fdopen(fd,'wb') as stream:
        stream.write(raw); stream.flush(); os.fsync(stream.fileno())


def reject_if_latched(state):
    path=state/'REJECTED.json'
    if path.exists() or path.is_symlink():
        raise ValueError('trace含永久策略拒绝标记REJECTED.json；即使configure忽略退出码也不得归档')


def read_rejection(build):
    """只读取固定prepared树首拒绝原件；不代表完整trace已经运输。"""
    build=pathlib.Path(build).resolve(); state=build/'.compact-profile'
    candidate=load(state/'receipt.json')
    receipt=verify_prepared(pathlib.Path(candidate['source']),build)
    receipt_raw,receipt_identity=read_stable(state/'receipt.json',CONFIG_MAX_BYTES)
    if decode_json(receipt_raw)!=receipt: raise ValueError('首拒绝读取期间prepared身份变化')
    binding={'source':receipt['source'],'build':receipt['build'],'module':receipt['descriptor']['module'],
             'preparedReceipt':receipt_identity}
    path=state/'REJECTED.json'
    if not path.exists() and not path.is_symlink():
        return {'status':'missing','reason':'固定prepared构建树未发现首拒绝回执',
                'sourceFile':{'path':'.compact-profile/REJECTED.json'},'binding':binding,
                'scope':'first-policy-rejection-only; not full trace'}
    raw,source_identity=read_stable(path,REJECTION_RECORD_BYTES)
    value=decode_json(raw)
    keys={'format','decision','executed','exitCode','nativeExitCode','elapsedSeconds','module','argv','originalArgv'}
    if not isinstance(value,dict) or set(value)!=keys or value['format']!=FORMAT or value['module']!=binding['module']:
        raise ValueError('首拒绝回执字段/模块身份不符')
    decision=value['decision']; original=value['originalArgv']
    if not isinstance(decision,dict) or set(decision)!={'rejected','reason'} or decision['rejected'] is not True \
            or not isinstance(decision['reason'],str) or len(decision['reason'])>2048 \
            or type(value['executed']) is not bool or type(value['exitCode']) is not int \
            or (value['nativeExitCode'] is not None and type(value['nativeExitCode']) is not int) \
            or type(value['elapsedSeconds']) not in (int,float) or not math.isfinite(value['elapsedSeconds']) or value['elapsedSeconds']<0:
        raise ValueError('首拒绝回执真实执行/错误状态非法')
    if not isinstance(original,dict) or set(original)!={'encoding','bytes','sha256','complete','omissionReason'} \
            or original['encoding']!='json-ascii-original-argv-v1' or type(original['bytes']) is not int or original['bytes']<=0 \
            or not isinstance(original['sha256'],str) or not re.fullmatch('[a-f0-9]{64}',original['sha256']) \
            or type(original['complete']) is not bool:
        raise ValueError('首拒绝原argv编码/字节身份非法')
    if original['complete']:
        if not isinstance(value['argv'],list) or not all(isinstance(arg,str) for arg in value['argv']) or original['omissionReason'] is not None:
            raise ValueError('首拒绝完整argv结构非法')
        actual=json.dumps(value['argv'],ensure_ascii=True,sort_keys=True,separators=(',',':')).encode('ascii')
        if len(actual)!=original['bytes'] or hashlib.sha256(actual).hexdigest()!=original['sha256']:
            raise ValueError('首拒绝完整argv字节/SHA不符')
        verification='complete-argv-encoding-bytes-sha256-verified'
    else:
        if value['argv'] is not None or original['bytes']<=REJECTION_RECORD_BYTES//2 \
                or not isinstance(original['omissionReason'],str) or not original['omissionReason']:
            raise ValueError('首拒绝省略argv状态非法')
        verification='argv-omitted-by-record-budget; original-bytes-sha256-reported-not-recomputed'
    # 损坏的孤立surrogate不能使外层UTF-8写出失败；明确作为读取边界失败交给secondary。
    try: json.dumps(value,ensure_ascii=False).encode('utf-8')
    except UnicodeEncodeError: raise ValueError('首拒绝回执包含无法安全运输的非UTF-8字符') from None
    if verify_prepared(pathlib.Path(receipt['source']),build)!=receipt:
        raise ValueError('首拒绝读取后prepared身份变化')
    return {'status':'present','receipt':value,'sourceFile':{'path':'.compact-profile/REJECTED.json',**source_identity},
            'binding':binding,'originalArgvVerification':verification,'scope':'first-policy-rejection-only; not full trace'}


def compiler_main(argv):
    started=time.monotonic(); state=None; receipt=None; options=None
    context={'executed':False,'nativeExitCode':None}
    try:
        parser = argparse.ArgumentParser(description=__doc__)
        parser.add_argument('--build',type=pathlib.Path,required=True)
        driver_options=parser.add_mutually_exclusive_group(required=True)
        driver_options.add_argument('--driver')
        driver_options.add_argument('--driver-base64')
        driver_options.add_argument('--encode-driver')
        parser.add_argument('arguments',nargs=argparse.REMAINDER)
        options = parser.parse_args(argv)
        build = options.build.resolve()
        candidate=load(build/'.compact-profile/receipt.json')
        verify_prepared(pathlib.Path(candidate['source']),build)
        # 只在完整prepared自验证之后持有可写state；配置不符不向任意--build留文件。
        receipt=candidate; state=build/'.compact-profile'
        if options.encode_driver is not None:
            if options.arguments: raise ValueError('驱动编码不接受编译参数')
            print(base64.b64encode(driver_bytes(options.encode_driver)).decode('ascii'),flush=True)
            return 0
        return execute_prepared(options,build,state,receipt,context,argv,started)
    except (Exception,SystemExit) as error:
        if isinstance(error,SystemExit) and not error.code: raise
        if options is None and state is None:
            # 参数解析失败也可能被configure吞掉；仅从唯一头部--build恢复并完整验证身份。
            try:
                header=argv[:argv.index('--')] if '--' in argv else argv
                builds=option_values(header,('--build',))
                if len(builds)==1:
                    build=pathlib.Path(builds[0]).resolve(); candidate=load(build/'.compact-profile/receipt.json')
                    verify_prepared(pathlib.Path(candidate['source']),build)
                    receipt=candidate; state=build/'.compact-profile'
            except Exception:
                pass
        if state is not None:
            try: rejection_latch(state,argv,error,receipt,context,started)
            except Exception as record_error:
                try: print('原拒绝后持久化回执失败：'+str(record_error),file=sys.stderr,flush=True)
                except Exception: pass
        if isinstance(error,SystemExit): raise ValueError('编译委派参数解析拒绝，原退出码'+str(error.code)) from error
        raise


def driver_bytes(text):
    if not isinstance(text,str) or not text or any(char in text for char in ('\x00','\n','\r')):
        raise ValueError('编译器原命令为空或含非法控制字符')
    raw=text.encode('utf-8')
    if len(raw)>TRACE_RECORD_BYTES//3: raise ValueError('编译器原命令超过记录预算')
    return raw


def execute_prepared(options, build, state, receipt, context, original_argv, invocation_started):
    driver_text=options.driver
    if options.driver_base64 is not None:
        token=options.driver_base64
        if len(token)>4*((TRACE_RECORD_BYTES//3+2)//3): raise ValueError('编译器编码超过记录预算')
        raw=base64.b64decode(token,validate=True)
        if base64.b64encode(raw).decode('ascii')!=token: raise ValueError('编译器编码不是规范base64')
        driver_text=raw.decode('utf-8')
        driver_bytes(driver_text)
    driver = json.loads(driver_text) if driver_text.startswith('[') else shlex.split(driver_text)
    if not isinstance(driver,list) or not driver or not all(isinstance(item,str) and item for item in driver):
        raise ValueError('真实编译器命令无效')
    args = options.arguments[1:] if options.arguments[:1] == ['--'] else options.arguments
    after, decision = rewrite_arguments(driver,args)
    decision['configureProbe']=controlled_configure_probe(build,[*driver[1:],*args])
    output_path=target_output_path(build,[*driver[1:],*after],decision['configureProbe']) if decision['compilation'] and decision['classification']=='target' else None
    queries=('--version','-version','-v','-V','-qversion','-dumpmachine','-dumpversion')
    decision['toolQuery']='--print-search-dirs' in [*driver[1:],*args] or \
        (len(args)==1 and (args[0] in queries or args[0].startswith(('-print-prog-name=','-print-file-name='))))
    executable = shutil.which(driver[0])
    if not executable: raise ValueError('真实编译器不存在')
    # Xcode工具链本身可含官方symlink；解析后固定其字节身份并在执行后复核。
    executable = pathlib.Path(executable).resolve()
    executable_id, executable_stat = compiler_identity(state,executable)
    number = reserve_record(state)
    record = {'format':FORMAT,'ordinal':number,'before':driver+args,'after':driver+after,'decision':decision,
              'cwd':os.getcwd(),'compiler':{'path':str(executable),**executable_id},'module':receipt['descriptor']['module'],
              'exitCode':None,'elapsedSeconds':None,'output':None,'evidenceError':None}
    started=time.monotonic(); code=125
    try:
        # 继承make的进程组和stdout/stderr；Runner超时清理仍覆盖实际编译器。
        process = subprocess.Popen([str(executable),*driver[1:],*after])
        context['executed']=True
        code = process.wait()
        context['nativeExitCode']=code
        record['exitCode']=code
        if code == 0:
            if list(stat_key(regular(executable))) != executable_stat: raise ValueError('编译器执行期间变化')
            verify_prepared(pathlib.Path(receipt['source']),build)
            if decision['compilation'] and decision['classification']=='target':
                if target_output_path(build,[*driver[1:],*after],decision['configureProbe'])!=output_path: raise ValueError('目标输出路径身份变化')
                # 受控探测可以有合法负结果或不生成对象，但不能作为库对象/Oz证据。
                if decision['configureProbe'] is None:
                    _, output_id = read_stable(output_path,object_file=True)
                    record['output']={'path':output_path.relative_to(build).as_posix(),**output_id,'format':'arm64-MH_OBJECT'}
    except Exception as error:
        record['evidenceError']=str(error)[:2048]
        if code == 0: code=125
    finally:
        record['elapsedSeconds']=time.monotonic()-started
        try: finish_record(state,number,record)
        except Exception as error:
            try: rejection_latch(state,original_argv,error,receipt,context,invocation_started,code if code else 125)
            except Exception: pass
            if code == 0: raise
            print('原编译失败后trace提交也失败：'+str(error),file=sys.stderr,flush=True)
    return code


def validate_record(record):
    keys={'format','ordinal','before','after','decision','cwd','compiler','module','exitCode',
          'elapsedSeconds','output','evidenceError'}
    if not isinstance(record,dict) or set(record)!=keys:
        raise ValueError('编译trace字段集合不符')
    decision=record['decision']
    if not isinstance(decision,dict) or set(decision)!={'classification','optimization','originalEffectiveOptimization',
                                                       'compilation','target','configureProbe','toolQuery'}:
        raise ValueError('编译trace策略字段不符')
    for name in ('before','after'):
        if not isinstance(record[name],list) or not record[name] or not all(isinstance(arg,str) for arg in record[name]):
            raise ValueError('编译trace argv不符')
    after, expected=rewrite_arguments(record['before'][:1],record['before'][1:])
    if record['after']!=record['before'][:1]+after or any(decision.get(key)!=value for key,value in expected.items()):
        raise ValueError('编译trace优化策略/实际argv不一致')
    if type(decision['toolQuery']) is not bool or \
            (record['exitCode'] is not None and type(record['exitCode']) is not int) or \
            type(record['elapsedSeconds']) not in (int,float) or not math.isfinite(record['elapsedSeconds']) or record['elapsedSeconds']<0:
        raise ValueError('编译trace退出码/计时类型非法')
    probe=decision['configureProbe']
    if probe is not None:
        if not isinstance(probe,dict) or set(probe)!={'source','bytes','sha256','configLog','configLogHeaderSha256'}:
            raise ValueError('configure探针身份字段非法')
        if not all(isinstance(probe[key],str) for key in ('source','configLog','sha256','configLogHeaderSha256')) or \
                type(probe['bytes']) is not int or not 0<=probe['bytes']<=1024**2 or \
                not all(re.fullmatch('[a-f0-9]{64}',probe[key]) for key in ('sha256','configLogHeaderSha256')):
            raise ValueError('configure探针源/日志字节身份非法')
        source=pathlib.PurePosixPath(probe['source']); log=pathlib.PurePosixPath(probe['configLog'])
        autoconf=source.name in CONFIGURE_PROBE_NAMES and log==source.with_name('config.log')
        if source.is_absolute() or '..' in source.parts or '\\' in str(source) or \
                not (autoconf or meson_probe_layout(source,log)):
            raise ValueError('configure探针源/日志路径非法')
    for value, extra in ((record['compiler'],{'path'}),(record['module'],set()),
                         (record['output'],{'path','format'})):
        if value is None and extra=={'path','format'}: continue
        if not isinstance(value,dict) or set(value)!={'bytes','sha256'}|extra or type(value['bytes']) is not int or value['bytes']<0 \
                or not isinstance(value['sha256'],str) or not re.fullmatch('[a-f0-9]{64}',value['sha256']):
            raise ValueError('编译trace字节身份非法')
    if record['output'] is not None:
        path=pathlib.PurePosixPath(record['output']['path'])
        if path.is_absolute() or '..' in path.parts or '\\' in str(path) or record['output']['bytes']<32:
            raise ValueError('编译trace对象路径非法')
    return record


TRACE_FAILURE_FORMAT = 'office-pdf-ios-first-invalid-trace-v1'
TRACE_FAILURE_BYTES = 8192
TRACE_FAILURE_REASONS = {'record-schema','format','ordinal','module','native-exit','evidence-error'}
TRACE_FAILURE_FLAGS = {'-c','-E','-S','-fsyntax-only','-v','-V','-qversion','--version','-version',
                       '-dumpversion','-dumpfullversion','-dumpmachine','--print-search-dirs','-x','-o','-Werror'}
TRACE_FAILURE_EXTENSIONS = {'.c','.cc','.cpp','.cxx','.m','.mm','.s','.S','.rc','.h','.o','.obj','.exe'}
TRACE_FAILURE_SOURCE_NAMES = set(CONFIGURE_PROBE_NAMES) | {'testfile.c','testfile.cc','testfile.cpp',
    'testfile.cxx','testfile.m','testfile.mm','sanitycheckc.c','sanitycheckcpp.cc'}


class TraceValidationError(ValueError):
    def __init__(self, message, detail):
        super().__init__(message)
        self.trace_failure = detail


def trace_evidence_error(error):
    # 错误正文可能含路径或参数；只投影固定类别、字节身份和errno，不运输原文。
    result={'present':error is not None,'kind':'none','bytes':0,'sha256':None,'errno':None}
    if error is None: return result
    if not isinstance(error,str):
        result.update(kind='invalid-type',bytes=None)
        return result
    raw=error.encode('utf-8',errors='backslashreplace')
    categories=(('目标编译输出不是普通arm64','object-format'),('profile路径包含链接','unsafe-file'),
        ('profile需要单链接普通文件','unsafe-file'),('profile文件超过预算','file-budget'),
        ('profile读取超过预算','file-budget'),('profile打开时身份变化','file-identity'),
        ('profile读取时身份变化','file-identity'),('编译器执行期间变化','compiler-identity'),
        ('续阶段真实编译器SHA变化','compiler-identity'),('目标输出路径身份变化','output-identity'),
        ('profile源/配置/模块身份不符','prepared-identity'),('profile配置身份变化','prepared-identity'),
        ('profile原始源码集合变化','prepared-identity'),('profile上游原件变化','prepared-identity'),
        ('profile临时目录绑定变化','prepared-identity'),('临时探测目录不是安全普通目录','prepared-identity'))
    kind=next((kind for prefix,kind in categories if error.startswith(prefix)),'unknown')
    number=re.match(r'^\[Errno ([0-9]{1,5})\]',error)
    result.update(kind='errno' if number else kind,bytes=len(raw),sha256=hashlib.sha256(raw).hexdigest(),
                  errno=int(number[1]) if number else None)
    return result


def trace_failure_summary(phase, name, raw, receipt, reasons, record=None):
    # 绑定同一次稳定读取的原字节；不加入原始argv、源码、完整路径或异常正文。
    detail={'status':'present','format':TRACE_FAILURE_FORMAT,'phase':phase,
        'sourceFile':{'path':'.compact-profile/trace/'+name,'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()},
        'reasons':reasons,'record':None,'binding':{'expectedModule':receipt['descriptor']['module']},
        'scope':'first-invalid-trace-summary-only; no raw argv/source/error'}
    if record is not None:
        before=record['before'];decision=record['decision'];code=record['exitCode'];ordinal=record['ordinal']
        module_bytes=record['module']['bytes']
        detail['record']={'ordinal':ordinal if type(ordinal) is int and 0<=ordinal<2**63 else None,
            'nativeExitCode':code if type(code) is int and -2**31<=code<2**31 else None,
            'classification':decision['classification'],'compilation':decision['compilation'],
            'configureProbe':decision['configureProbe'] is not None,'toolQuery':decision['toolQuery'],
            'module':{'bytes':module_bytes if module_bytes<2**63 else None,'sha256':record['module']['sha256']},
            'evidenceError':trace_evidence_error(record['evidenceError']),
            'argumentShape':{'beforeCount':len(before),'afterCount':len(record['after']),
                'knownFlags':sorted(set(before)&TRACE_FAILURE_FLAGS),
                'sourceExtensions':sorted({pathlib.PurePosixPath(a).suffix for a in before}&TRACE_FAILURE_EXTENSIONS),
                'configureSourceNames':sorted({pathlib.PurePosixPath(a).name for a in before}&TRACE_FAILURE_SOURCE_NAMES),
                'definitionCount':sum(a.startswith('-D') for a in before),
                'includeCount':sum(a.startswith('-I') for a in before),'hasStdin':'-' in before}}
    return detail


def read_trace_failure(error):
    if not isinstance(error,TraceValidationError):
        return {'status':'unavailable','reason':'错误未提供首失效记录摘要'}
    detail=error.trace_failure
    def require(value):
        if not value: raise ValueError('首失效trace摘要结构或预算不符')
    def identity_ok(value, nullable=False):
        return isinstance(value,dict) and set(value)=={'bytes','sha256'} and \
            ((nullable and value['bytes'] is None) or type(value['bytes']) is int and 0<=value['bytes']<2**63) and \
            isinstance(value['sha256'],str) and re.fullmatch('[a-f0-9]{64}',value['sha256']) is not None
    require(isinstance(detail,dict) and set(detail)=={'status','format','phase','sourceFile','reasons','record','binding','scope'})
    require(detail['status']=='present' and detail['format']==TRACE_FAILURE_FORMAT and detail['phase'] in ('tools','vcl','sd','sw','final'))
    require(detail['scope']=='first-invalid-trace-summary-only; no raw argv/source/error')
    source=detail['sourceFile']
    require(isinstance(source,dict) and set(source)=={'path','bytes','sha256'} and
            isinstance(source['path'],str) and re.fullmatch(r'\.compact-profile/trace/[0-9]{8}\.json',source['path']) is not None)
    require(identity_ok({k:source[k] for k in ('bytes','sha256')}) and source['bytes']<=TRACE_RECORD_BYTES)
    require(isinstance(detail['reasons'],list) and 0<len(detail['reasons'])<=len(TRACE_FAILURE_REASONS) and
            all(isinstance(r,str) and r in TRACE_FAILURE_REASONS for r in detail['reasons']))
    binding=detail['binding']
    require(isinstance(binding,dict) and set(binding)=={'expectedModule'} and identity_ok(binding['expectedModule']))
    record=detail['record']
    if record is None:
        require(detail['reasons']==['record-schema'])
    else:
        require(isinstance(record,dict) and set(record)=={'ordinal','nativeExitCode','classification','compilation','configureProbe','toolQuery','module','evidenceError','argumentShape'})
        require(record['ordinal'] is None or type(record['ordinal']) is int and 0<=record['ordinal']<2**63)
        require(record['nativeExitCode'] is None or type(record['nativeExitCode']) is int and -2**31<=record['nativeExitCode']<2**31)
        require(record['classification'] in ('host','target','probe') and all(type(record[k]) is bool for k in ('compilation','configureProbe','toolQuery')))
        require(identity_ok(record['module'],nullable=True))
        evidence=record['evidenceError']
        require(isinstance(evidence,dict) and set(evidence)=={'present','kind','bytes','sha256','errno'} and type(evidence['present']) is bool)
        require(evidence['kind'] in ('none','invalid-type','object-format','unsafe-file','file-budget','file-identity','compiler-identity','output-identity','prepared-identity','errno','unknown'))
        require(evidence['bytes'] is None or type(evidence['bytes']) is int and 0<=evidence['bytes']<=TRACE_RECORD_BYTES)
        require(evidence['sha256'] is None or isinstance(evidence['sha256'],str) and re.fullmatch('[a-f0-9]{64}',evidence['sha256']) is not None)
        require(evidence['errno'] is None or type(evidence['errno']) is int and 0<=evidence['errno']<=99999)
        shape=record['argumentShape']
        require(isinstance(shape,dict) and set(shape)=={'beforeCount','afterCount','knownFlags','sourceExtensions','configureSourceNames','definitionCount','includeCount','hasStdin'})
        require(all(type(shape[k]) is int and 0<=shape[k]<=TRACE_RECORD_BYTES for k in ('beforeCount','afterCount','definitionCount','includeCount')) and type(shape['hasStdin']) is bool)
        for key,allowed in (('knownFlags',TRACE_FAILURE_FLAGS),('sourceExtensions',TRACE_FAILURE_EXTENSIONS),('configureSourceNames',TRACE_FAILURE_SOURCE_NAMES)):
            require(isinstance(shape[key],list) and len(shape[key])<=len(allowed) and all(isinstance(x,str) and x in allowed for x in shape[key]))
    raw=encoded(detail);require(len(raw)<=TRACE_FAILURE_BYTES)
    return decode_json(raw)


def collect_trace(build, phase):
    if phase not in ('tools','vcl','sd','sw','final'): raise ValueError('未知trace阶段')
    build = pathlib.Path(build).resolve(); state = build/'.compact-profile'
    receipt = load(state/'receipt.json'); verify_prepared(pathlib.Path(receipt['source']),build)
    reject_if_latched(state)
    with locked(state):
        reject_if_latched(state)
        ledger = read_ledger(state)
        if ledger['pending'] or ledger['count'] > TRACE_MAX_RECORDS or ledger['bytes'] > TRACE_MAX_BYTES:
            raise ValueError('trace未完整完成或预算超限')
        paths = sorted((state/'trace').iterdir())
        if [p.name for p in paths] != [f'{n:08d}.json' for n in range(1,ledger['count']+1)]:
            raise ValueError('trace记录集合不连续或存在陌生文件')
        total=0; digest=hashlib.sha256(); oz=0; low=0; host=0; unknown=0; probes=0; failed_probes=0
        families={name:0 for name in ('vcl','sd','sw')}; before_counts={}
        for number,path in enumerate(paths,1):
            raw,_ = read_stable(path,TRACE_RECORD_BYTES); total+=len(raw)
            if total > TRACE_MAX_BYTES: raise ValueError('trace总大小超限')
            try:
                record = validate_record(decode_json(raw))
            except ValueError as error:
                raise TraceValidationError(str(error)+'；记录'+path.name,
                    trace_failure_summary(phase,path.name,raw,receipt,['record-schema'])) from error
            decision=record['decision']; output=record['output']
            probe=bool(decision.get('configureProbe') or decision.get('toolQuery'))
            reasons=[]
            if record['format']!=FORMAT: reasons.append('format')
            if record['ordinal']!=number: reasons.append('ordinal')
            if record['module']!=receipt['descriptor']['module']: reasons.append('module')
            if record['exitCode']!=0 and not probe: reasons.append('native-exit')
            if record['evidenceError'] is not None: reasons.append('evidence-error')
            if reasons:
                raise TraceValidationError('trace存在失败编译或身份不符；记录'+path.name+'；原因'+','.join(reasons),
                    trace_failure_summary(phase,path.name,raw,receipt,reasons,record))
            digest.update(path.name.encode()+b'\0'+raw)
            if probe:
                probes+=1
                if record['exitCode']!=0: failed_probes+=1
                continue
            if decision['classification']=='host': host+=1
            if decision['classification']=='target' and decision['compilation']:
                effective=decision['originalEffectiveOptimization'] or 'unspecified'
                before_counts[effective]=before_counts.get(effective,0)+1
                if decision['optimization']=='Oz':
                    if record['after'][-1]!='-Oz' or not output or output['format']!='arm64-MH_OBJECT':
                        raise ValueError('trace缺少真实Oz普通对象证据')
                    oz+=1
                    for family in families:
                        if family in pathlib.PurePosixPath(output['path']).parts: families[family]+=1
                elif decision['optimization']=='explicit-low': low+=1
                else: unknown+=1
        if total != ledger['bytes']: raise ValueError('trace账本字节不符')
        metadata=sum(regular(path).st_size for path in state.iterdir() if path.name not in ('trace','lock'))
        if metadata>STATE_METADATA_RESERVE or total+metadata>TRACE_MAX_BYTES:
            raise ValueError('trace树含元数据超过128MiB总预算')
        for path in sorted(state.glob('compiler-*.json')):
            compiler=load(path); executable=pathlib.Path(compiler['path'])
            # 续阶段/阶段归档前重新全文SHA；逐调用仅核稳定stat，不宣称逐调用全文哈希。
            expected,fingerprint=compiler_identity_unlocked(executable)
            if expected!=compiler['identity'] or fingerprint!=compiler['stat']: raise ValueError('阶段编译器SHA/身份变化')
        required=('vcl','sd','sw')[:{'tools':0,'vcl':1,'sd':2,'sw':3,'final':3}[phase]]
        if any(not families[name] for name in required): raise ValueError('缺少阶段对应库真实Oz编译证据')
        summary={'format':FORMAT,'phase':phase,'descriptor':receipt['descriptor'],'traceRecords':len(paths),
                 'traceBytes':total,'traceSetSha256':digest.hexdigest(),'targetOzCompilations':oz,
                 'explicitLowCompilations':low,'unchangedHostInvocations':host,'unspecifiedOptimizationCompilations':unknown,
                 'configureAndToolProbeInvocations':probes,'negativeProbeInvocations':failed_probes,
                 'originalEffectiveOptimizationCounts':before_counts,'libraryOzObjects':families,
                 'coverageUnknown':True,'coverageBoundary':'only delegated invocations; standalone assembler and other compiler variables not inferred',
                 'rawTraceTransported':False,'rawTracePersistenceVerified':False,
                 'rawTraceRetention':('runner temporary build tree only; final build tree is not checkpointed' if phase=='final'
                                      else 'eligible for successful-stage build checkpoint; actual cache persistence requires separate receipt'),
                 'appleCompileVerified':False,'available':False}
        # 阶段摘要不进入稳定identity；非final树可进入检查点，final新增全trace仅在runner临时树。
        reject_if_latched(state)
        replace_json(state/('summary-'+phase+'.json'),summary)
        reject_if_latched(state)
        return summary


if __name__ == '__main__':
    try: raise SystemExit(compiler_main(sys.argv[1:]))
    except (OSError,ValueError,RuntimeError,subprocess.SubprocessError) as error:
        print('compact编译委派拒绝：'+str(error),file=sys.stderr,flush=True)
        raise SystemExit(125)

