// 路径、同一fd及读取后身份共同约束；不跟随资源目录/文件链接，不将读失败当空SHA。
NSString *resourceFileSHA256(NSString *root, NSString *relative, unsigned long long limit,
                           unsigned long long *size, NSData **contents = nullptr, struct stat *identity = nullptr) {
    if (!resourceDirectory(root) || !resourceRelativePath(relative)) return nil;
    ResourceFD directory(open(root.fileSystemRepresentation, O_RDONLY | O_DIRECTORY | O_NOFOLLOW));
    if (directory.value < 0) return nil;
    struct stat rootBefore;
    if (fstat(directory.value, &rootBefore) != 0) return nil;
    NSArray *parts = [relative componentsSeparatedByString:@"/"];
    for (NSUInteger index = 0; index + 1 < parts.count; ++index) {
        int next = openat(directory.value, [parts[index] fileSystemRepresentation], O_RDONLY | O_DIRECTORY | O_NOFOLLOW);
        if (next < 0) return nil;
        close(directory.value); directory.value = next;
    }
    const char *leaf = [parts.lastObject fileSystemRepresentation];
    struct stat before, opened, after, pathAfter, rootAfter;
    if (fstatat(directory.value, leaf, &before, AT_SYMLINK_NOFOLLOW) != 0 ||
        !S_ISREG(before.st_mode) || before.st_nlink != 1 || before.st_size < 0 ||
        static_cast<unsigned long long>(before.st_size) > limit) return nil;
    ResourceFD file(openat(directory.value, leaf, O_RDONLY | O_NOFOLLOW));
    if (file.value < 0 || fstat(file.value, &opened) != 0 || !sameResourceStat(before, opened)) return nil;
    CC_SHA256_CTX digest; CC_SHA256_Init(&digest);
    NSMutableData *data = contents ? [NSMutableData data] : nil;
    unsigned char buffer[65536]; unsigned long long total = 0;
    while (true) {
        ssize_t count = read(file.value, buffer, sizeof(buffer));
        if (count < 0 && errno == EINTR) continue;
        if (count < 0) return nil;
        if (count == 0) break;
        total += static_cast<unsigned long long>(count);
        if (total > limit || total > static_cast<unsigned long long>(before.st_size)) return nil;
        CC_SHA256_Update(&digest, buffer, static_cast<CC_LONG>(count));
        if (contents) [data appendBytes:buffer length:static_cast<NSUInteger>(count)];
    }
    NSString *path = [root stringByAppendingPathComponent:relative];
    if (total != static_cast<unsigned long long>(before.st_size) || fstat(file.value, &after) != 0 ||
        lstat(path.fileSystemRepresentation, &pathAfter) != 0 ||
        lstat(root.fileSystemRepresentation, &rootAfter) != 0 || !sameResourceStat(before, after) ||
        !sameResourceStat(before, pathAfter) || !sameResourceStat(rootBefore, rootAfter) ||
        !resourceCanonicalPathMatches(path)) return nil;
    unsigned char hash[CC_SHA256_DIGEST_LENGTH]; CC_SHA256_Final(hash, &digest);
    NSMutableString *hex = [NSMutableString stringWithCapacity:64];
    for (unsigned char value : hash) [hex appendFormat:@"%02x", value];
    if (size) *size = total;
    if (contents) *contents = data;
    if (identity) *identity = after;
    return hex;
}
bool resourceKeys(id value, NSArray *keys) {
    return [value isKindOfClass:NSDictionary.class] &&
        [[NSSet setWithArray:[value allKeys]] isEqualToSet:[NSSet setWithArray:keys]];
}
bool resourceSize(id value) {
    if (![value isKindOfClass:NSNumber.class] || CFGetTypeID((__bridge CFTypeRef)value) == CFBooleanGetTypeID()) return false;
    const char *kind = [value objCType];
    return kind && strlen(kind) == 1 && strchr("cCsSiIlLqQ", kind[0]) &&
        [value doubleValue] >= 0 && [value doubleValue] <= 512ULL * 1024 * 1024;
}
bool resourceSHA(id value) {
    return [value isKindOfClass:NSString.class] && [value length] == 64 &&
        [value rangeOfCharacterFromSet:[[NSCharacterSet characterSetWithCharactersInString:@"0123456789abcdef"] invertedSet]].location == NSNotFound;
}
bool resourcesValid(NSString *root) {
    if (!resourceDirectory(root)) return false;
    NSFileManager *files = NSFileManager.defaultManager;
    for (NSString *name in @[@"program", @"share"])
        if (!resourceDirectory([root stringByAppendingPathComponent:name])) return false;
    NSData *bytes = nil;
    struct stat manifestStat;
    if (!resourceFileSHA256(root, @"OfficePdfKernelManifest.json", 4 * 1024 * 1024, nullptr, &bytes, &manifestStat) || bytes.length == 0) return false;
    id manifest = [NSJSONSerialization JSONObjectWithData:bytes options:0 error:nil];
    if (!resourceKeys(manifest, @[@"sourceTag", @"sourceCommit", @"offlinePolicy", @"buildCompatibility", @"layout", @"mainICU", @"resources"]) ||
        ![manifest[@"sourceTag"] isEqual:@"libreoffice-26.2.6.3"] ||
        ![manifest[@"sourceCommit"] isEqual:@"8221e31b3ac356a1623c672912a3d2b492f7e3d1"] ||
        ![manifest[@"layout"] isEqual:@"single-main-icu-v1"] ||
        ![manifest[@"buildCompatibility"] isKindOfClass:NSDictionary.class] ||
        ![manifest[@"resources"] isKindOfClass:NSArray.class] ||
        [manifest[@"resources"] count] == 0 || [manifest[@"resources"] count] > 10000) return false;
    id policy = manifest[@"offlinePolicy"];
    if (![policy isKindOfClass:NSDictionary.class] ||
        ![policy[@"policyId"] isEqual:@"lizhao-office-pdf-ios-offline-candidate-v1"] ||
        strlen(OFFICE_PDF_POLICY_SHA256) != 64 ||
        ![policy[@"policySha256"] isEqual:[NSString stringWithUTF8String:OFFICE_PDF_POLICY_SHA256]]) return false;
    id mainICU = manifest[@"mainICU"];
    if (!resourceKeys(mainICU, @[@"path", @"bytes", @"sha256"]) || ![mainICU[@"path"] isEqual:@"ICU.dat"] ||
        !resourceSize(mainICU[@"bytes"]) || [mainICU[@"bytes"] unsignedLongLongValue] != 33107232 ||
        ![mainICU[@"sha256"] isEqual:@"d5cf2a40dccbe471781ec7af85693bff542ff12f0b670c9630c4e72d60714b8b"]) return false;
    NSMutableSet *expectedFiles = [NSMutableSet set];
    NSMutableDictionary *fileStats = [NSMutableDictionary dictionary];
    bool foundRC = false, foundFundamentalRC = false;
    for (id item in manifest[@"resources"]) {
        if (!resourceKeys(item, @[@"path", @"bytes", @"sha256"])) return false;
        id relative = item[@"path"], size = item[@"bytes"], expected = item[@"sha256"];
        if (!resourceRelativePath(relative) || !resourceSize(size) || !resourceSHA(expected) ||
            [expectedFiles containsObject:relative] ||
            [@[@"ICU.dat", @"icudt78l.dat", @"OfficePdfKernelManifest.json"] containsObject:relative]) return false;
        unsigned long long actualSize = 0;
        struct stat identity;
        if (![resourceFileSHA256(root, relative, 512ULL * 1024 * 1024, &actualSize, nullptr, &identity) isEqual:expected] ||
            actualSize != [size unsignedLongLongValue]) return false;
        fileStats[relative] = [NSValue valueWithBytes:&identity objCType:@encode(struct stat)];
        if ([relative isEqual:@"rc"] && actualSize > 0) foundRC = true;
        if ([relative isEqual:@"fundamentalrc"] && actualSize > 0) foundFundamentalRC = true;
        [expectedFiles addObject:relative];
    }
    if (!foundRC || !foundFundamentalRC) return false;
    [expectedFiles addObject:@"OfficePdfKernelManifest.json"];
    NSMutableSet *actualFiles = [NSMutableSet set];
    NSDirectoryEnumerator *enumerator = [files enumeratorAtPath:root];
    if (!enumerator) return false;
    for (NSString *relative in enumerator) {
        if (!resourceRelativePath(relative)) return false;
        struct stat info;
        if (lstat([root stringByAppendingPathComponent:relative].fileSystemRepresentation, &info) != 0) return false;
        if (S_ISREG(info.st_mode)) [actualFiles addObject:relative];
        else if (!S_ISDIR(info.st_mode)) return false;
    }
    if (![actualFiles isEqualToSet:expectedFiles]) return false;
    fileStats[@"OfficePdfKernelManifest.json"] = [NSValue valueWithBytes:&manifestStat objCType:@encode(struct stat)];
    for (NSString *relative in fileStats) {
        struct stat before, after;
        [fileStats[relative] getValue:&before size:sizeof(before)];
        NSString *file = [root stringByAppendingPathComponent:relative];
        if (lstat(file.fileSystemRepresentation, &after) != 0 || !sameResourceStat(before, after) ||
            !resourceCanonicalPathMatches(file)) return false;
    }
    // 固定上游init.cxx只从App主包初始化完整ICU；禁止外部路径或旧三副本manifest回退。
    unsigned long long mainSize = 0;
    NSString *mainRoot = resourceCanonicalPath(NSBundle.mainBundle.bundlePath);
    NSString *mainHash = resourceFileSHA256(mainRoot, @"ICU.dat", 512ULL * 1024 * 1024, &mainSize);
    return mainSize == [mainICU[@"bytes"] unsignedLongLongValue] && [mainHash isEqual:mainICU[@"sha256"]];
