def instrument_returns(helpers, first_line):
    """只包装词法return表达式并保持求值一次；拒绝不能可靠映射的源码。"""
    token = re.compile(r'//[^\n]*|/\*.*?\*/|"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|\breturn\b', re.S)
    matches = list(token.finditer(helpers))
    spans = [(item.start(), item.end()) for item in matches if item.group() == 'return']
    pieces, mapping, offset, generated_size = [], [], 0, 0
    for start, end in spans:
        if start < offset:
            raise ValueError('nested return cannot be mapped')
        cursor = end
        while cursor < len(helpers):
            item = token.match(helpers, cursor)
            if item:
                cursor = item.end()
            elif helpers[cursor] == ';':
                break
            else:
                cursor += 1
        if cursor == len(helpers):
            raise ValueError('unterminated return cannot be mapped')
        expression = helpers[end:cursor]
        if not expression.strip():
            raise ValueError('void return is outside resource-helper contract')
        line = first_line + helpers[:start].count('\n')
        original = helpers[start:cursor + 1]
        declarations = list(re.finditer(r'^(?:bool |NSString \*)([A-Za-z][A-Za-z0-9_]*)\(', helpers[:start], re.M))
        function = declarations[-1].group(1) if declarations else ''
        context = {'resourceCanonicalPath': ', nil, nil, value', 'resourceCanonicalPathMatches': ', nil, nil, value',
                   'resourceDirectory': ', root', 'resourceFileSHA256': ', root, relative',
                   'resourceSize': ', nil, nil, value', 'resourceRelativePath': ', nil, nil, value',
                   'resourceSHA': ', nil, nil, value'}.get(function, '')
        wrapped = 'return diagnosticReturn((' + expression + '), ' + str(line) + ', __func__' + context + ');'
        prefix = helpers[offset:start]
        pieces.extend((prefix, wrapped))
        generated_size += len(prefix)
        mapping.append({'sourceLine': line, 'original': original, 'generatedStart': generated_size,
                        'generatedEnd': generated_size + len(wrapped)})
        generated_size += len(wrapped)
        offset = cursor + 1
    if not mapping:
        raise ValueError('no resource returns found')
    pieces.append(helpers[offset:])
    return ''.join(pieces), mapping


