    id main = value[@"mainICU"], rows = value[@"resources"];
    if ([main isKindOfClass:NSDictionary.class]) result[@"mainICUBytes"] = diagnosticType(main[@"bytes"]);
    NSMutableSet *expected = [NSMutableSet setWithObject:@"OfficePdfKernelManifest.json"];
    NSMutableArray *sizes = [NSMutableArray array];
    if ([rows isKindOfClass:NSArray.class]) {
        result[@"resourceCount"] = @([rows count]);
        if ([rows count] > 32) return @{ @"error": @"fixture-manifest-row-budget", @"resourceCount": @([rows count]) };
        for (id row in rows) {
            if (![row isKindOfClass:NSDictionary.class]) continue;
            id relative = row[@"path"];
            [sizes addObject:@{ @"path": [relative isKindOfClass:NSString.class] ? diagnosticText(relative) : NSNull.null,
                               @"bytes": diagnosticType(row[@"bytes"]), @"shaType": diagnosticType(row[@"sha256"]) }];
            if ([relative isKindOfClass:NSString.class]) [expected addObject:relative];
        }
    }
    result[@"resourceTypes"] = sizes;
    NSMutableSet *actual = [NSMutableSet set]; NSUInteger visited = 0;
    NSDirectoryEnumerator *enumerator = [NSFileManager.defaultManager enumeratorAtPath:root];
    if (!enumerator) { result[@"enumerationError"] = @"nil enumerator"; return result; }
    for (NSString *relative in enumerator) {
        if (++visited > 64) { result[@"enumerationError"] = @"fixture-enumeration-budget"; break; }
        NSDictionary *entry = diagnosticStat([root stringByAppendingPathComponent:relative]);
        if ([entry[@"type"] isEqual:@"regular"]) [actual addObject:relative];
        else if (![entry[@"type"] isEqual:@"directory"]) {
            result[@"enumerationError"] = @{ @"path": diagnosticText(relative), @"lstat": entry }; break;
        }
    }
    NSMutableSet *missing = [expected mutableCopy], *extra = [actual mutableCopy];
    [missing minusSet:actual]; [extra minusSet:expected];
    NSMutableArray *missingText = [NSMutableArray array], *extraText = [NSMutableArray array];
    for (NSString *entry in [[missing allObjects] sortedArrayUsingSelector:@selector(compare:)]) [missingText addObject:diagnosticText(entry)];
    for (NSString *entry in [[extra allObjects] sortedArrayUsingSelector:@selector(compare:)]) [extraText addObject:diagnosticText(entry)];
    result[@"enumerationDifference"] = @{ @"missing": missingText, @"extra": extraText,
        @"expectedCount": @(expected.count), @"actualCount": @(actual.count), @"visited": @(visited) };
    return result;
}

// 此函数仅用于测试侧诊断；先绑定原NSData再创建fallback，绝不把fallback SHA当原体SHA。
static NSData *diagnosticSerializeReport(NSDictionary *report) {
    NSError *error = nil;
    NSData *data = nil;
    NSString *unavailable = @"NSJSONSerialization produced no NSData";
    @try {
        data = [NSJSONSerialization dataWithJSONObject:report options:NSJSONWritingSortedKeys error:&error];
    } @catch (NSException *exception) {
        unavailable = [@"NSJSONSerialization exception " stringByAppendingString:exception.name];
    }
    if (data && data.length <= 24576) return data;
    NSMutableDictionary *omitted = [@{
        @"available": @(data != nil), @"bytes": data ? @(data.length) : (id)NSNull.null,
        @"sha256": NSNull.null, @"encoding": @"UTF-8 NSJSONSerialization bytes",
        @"trailingLFIncluded": @NO, @"scope": @"original-native-json-before-fallback" } mutableCopy];
    if (data) {
        CC_SHA256_CTX digest; CC_SHA256_Init(&digest);
        const unsigned char *bytes = static_cast<const unsigned char *>(data.bytes);
        NSUInteger offset = 0;
        while (offset < data.length) {
            NSUInteger count = data.length - offset;
            if (count > 65536) count = 65536;
            CC_SHA256_Update(&digest, bytes + offset, static_cast<CC_LONG>(count));
            offset += count;
        }
        unsigned char hash[CC_SHA256_DIGEST_LENGTH]; CC_SHA256_Final(hash, &digest);
        NSMutableString *hex = [NSMutableString stringWithCapacity:64];
        for (unsigned char value : hash) [hex appendFormat:@"%02x", value];
        omitted[@"sha256"] = hex;
    } else {
        omitted[@"unavailableReason"] = unavailable;
    }
    NSDictionary *fallback = @{ @"accepted": report[@"accepted"] ?: (id)NSNull.null,
        @"firstReject": report[@"firstReject"] ?: (id)NSNull.null,
        @"diagnosticError": data ? @"native-report-budget" : @"native-serialization-error",
        @"omittedBytes": data ? @(data.length) : (id)NSNull.null, @"omittedJSON": omitted,
        @"errorCode": error ? @(error.code) : (id)NSNull.null };
    return [NSJSONSerialization dataWithJSONObject:fallback options:0 error:nil];
}

"""

DIAGNOSTIC_MAIN = r"""
int main(int argc, const char **argv) { @autoreleasepool {
    if (argc != 3) return 2;
    testMainBundle = [NSString stringWithUTF8String:argv[2]];
    NSString *root = [NSString stringWithUTF8String:argv[1]];
    bool accepted = resourcesValid(root);
    // 所有额外Foundation/POSIX探针均发生在原条件已完成之后。
    NSMutableDictionary *paths = [NSMutableDictionary dictionary];
    NSDictionary *inputs = @{ @"bundle": root, @"program": [root stringByAppendingPathComponent:@"program"],
        @"share": [root stringByAppendingPathComponent:@"share"],
        @"manifest": [root stringByAppendingPathComponent:@"OfficePdfKernelManifest.json"],
        @"nested": [root stringByAppendingPathComponent:@"program/registry/test.xcd"],
        @"empty": [root stringByAppendingPathComponent:@"program/empty"],
        @"mainRoot": testMainBundle, @"mainICU": [testMainBundle stringByAppendingPathComponent:@"ICU.dat"] };
    for (NSString *key in inputs) paths[key] = diagnosticPath(inputs[key]);
    NSDictionary *report = @{ @"accepted": @(accepted), @"firstReject": firstReject ?: (id)NSNull.null,
        @"paths": paths, @"manifest": diagnosticManifest(root),
        @"macOS": NSProcessInfo.processInfo.operatingSystemVersionString };
    NSData *data = diagnosticSerializeReport(report);
    if (data) { fwrite(data.bytes, 1, data.length, stdout); fputc('\n', stdout); }
    return accepted ? 0 : 1;
}}
"""


def validator_program(source, diagnostic=False):
    start, end = source.index('bool sameResourceStat('), source.index('// Kit对象只在持锁工作线程')
    raw = source[start:end]
    helpers = raw.replace('NSBundle.mainBundle.bundlePath', 'testMainBundle')
    helpers = helpers.replace('33107232', str(IDENTITY[0])).replace(
        'd5cf2a40dccbe471781ec7af85693bff542ff12f0b670c9630c4e72d60714b8b', IDENTITY[1])
    prefix = '#import <Foundation/Foundation.h>\n#import <CommonCrypto/CommonDigest.h>\n#include <sys/stat.h>\n#include <fcntl.h>\n#include <unistd.h>\n#include <cstdlib>\n#include <limits.h>\n#include <cmath>\n#include <cstring>\n#include <cerrno>\n#define OFFICE_PDF_POLICY_SHA256 "' + POLICY['policySha256'] + '"\nNSString *testMainBundle;\n'
    main = '\nint main(int argc, const char **argv) { @autoreleasepool { if(argc!=3)return 2; testMainBundle=[NSString stringWithUTF8String:argv[2]]; return resourcesValid([NSString stringWithUTF8String:argv[1]])?0:1; }}\n'
    first_line = source[:start].count('\n') + 1
    fixture_helper_sha = hashlib.sha256(helpers.encode()).hexdigest()
    mapping = []
    if diagnostic:
        helpers, mapping = instrument_returns(helpers, first_line)
        prefix += DIAGNOSTIC_SUPPORT + '\n#line ' + str(first_line) + ' "src/OfficePdfKernel.mm"\n'
        main = '\n#line 1 "test-resource-diagnostic-main.mm"\n' + DIAGNOSTIC_MAIN
    program = prefix + helpers + main
    return program, {'originalSourceSha256': hashlib.sha256(source.encode()).hexdigest(),
                     'originalHelperSha256': hashlib.sha256(raw.encode()).hexdigest(),
                     'sourceHashRepresentation': 'UTF-8 after original universal-newline extraction; see originalDiskSource for physical file/helper SHA',
                     'fixtureHelperSha256': fixture_helper_sha,
                     'programSha256': hashlib.sha256(program.encode()).hexdigest(),
                     'instrumented': diagnostic, 'returnSourceLines': [row['sourceLine'] for row in mapping]}


def diagnostic_command(argv, timeout, stream_limit=DIAGNOSTIC_STREAM_LIMIT):
    """流写临时文件再有界读取，不把编译器/原生任意输出灌入工具日志或内存。"""
    def read_stream(stream):
        stream.seek(0)
        digest, count, prefix = hashlib.sha256(), 0, bytearray()
        while True:
            raw = stream.read(65536)
            if not raw: break
            digest.update(raw); count += len(raw)
            if len(prefix) < stream_limit:
                prefix.extend(raw[:stream_limit - len(prefix)])
        result = {'bytes': count, 'sha256': digest.hexdigest(), 'complete': count <= stream_limit,
                  'text': bytes(prefix).decode('utf-8', errors='backslashreplace')}
        if not result['complete']: result['omissionReason'] = 'diagnostic-stream-budget'
        return result
    with tempfile.TemporaryFile() as stdout, tempfile.TemporaryFile() as stderr:
        try:
            result = subprocess.run(argv, stdout=stdout, stderr=stderr, timeout=timeout, check=False)
            code, error = result.returncode, None
        except (OSError, subprocess.TimeoutExpired) as exc:
            code, error = None, type(exc).__name__ + ': ' + str(exc)[:512]
        result = {'argv': argv, 'returncode': code, 'stdout': read_stream(stdout), 'stderr': read_stream(stderr)}
        if error: result['error'] = error
        return result


class DiagnosticLogBudget:
    def __init__(self, per_report=DIAGNOSTIC_REPORT_LIMIT, total=DIAGNOSTIC_TOTAL_LIMIT):
        self.per_report, self.total, self.used, self.exhausted = per_report, total, 0, False

    def encode(self, report):
        if self.exhausted: return b''  # 前一终止回执明确说明后续全部抑制。
        def encode(value):
            return b'COMPACT_RESOURCE_DIAGNOSTIC ' + json.dumps(value, ensure_ascii=True, allow_nan=False, separators=(',', ':')).encode() + b'\n'
        try:
            raw = encode(report)
        except Exception as exc:
            raw = encode({'baselineReturncode': report.get('baselineReturncode'),
                          'diagnosticError': 'report-serialization-failed: ' + type(exc).__name__})
        if len(raw) > self.per_report:
            raw = encode({'baselineReturncode': report.get('baselineReturncode'), 'diagnosticError': 'report-budget-exceeded',
                          'omittedReportBytes': len(raw), 'omittedReportSha256': hashlib.sha256(raw).hexdigest(),
                          'firstReject': report.get('native', {}).get('firstReject'),
                          'firstRejectSource': report.get('firstRejectSource'),
                          'baseline': report.get('baseline'), 'diagnostic': report.get('diagnostic'),
                          'secondaryError': report.get('diagnosticError'),
                          'nativeOmittedJSON': report.get('native', {}).get('omittedJSON')})
        # 留512B给唯一总预算终止回执，之后不再尝试诊断/编译。
        if self.used + len(raw) > self.total - 512:
            raw = encode({'baselineReturncode': report.get('baselineReturncode'), 'diagnosticError': 'total-log-budget-exhausted',
                          'futureReportsSuppressed': True, 'usedBytes': self.used, 'totalLimitBytes': self.total})
            self.exhausted = True
        if len(raw) > self.per_report or self.used + len(raw) > self.total:
            raise ValueError('diagnostic budget too small for explicit omission receipt')
        self.used += len(raw)
        return raw


RESOURCE_DIAGNOSTIC_BUDGET = DiagnosticLogBudget()


def diagnostic_file(path, limit=4 * 1024 * 1024):
    info = path.lstat()
    result = {'bytes': info.st_size, 'mode': info.st_mode, 'nlink': info.st_nlink}
    if not stat.S_ISREG(info.st_mode) or info.st_size > limit:
        return {**result, 'error': 'not-small-regular-fixture-file', 'sha256': None}
    with path.open('rb') as stream:
        raw = stream.read(limit + 1)
    if len(raw) > limit: raise ValueError('fixture file grew past diagnostic budget')
    return {**result, 'bytes': len(raw), 'sha256': hashlib.sha256(raw).hexdigest()}


def validate_native_omission(native, original=None):
    """外层只验回执结构；仅独立持有原NSData字节的Mac回归可重算原体SHA。"""
    kind = native.get('diagnosticError')
    if kind not in ('native-report-budget', 'native-serialization-error'): return None
    receipt = native.get('omittedJSON')
    if not isinstance(receipt, dict) or type(receipt.get('available')) is not bool:
        raise ValueError('native omitted JSON availability is unknown')
    if receipt.get('encoding') != 'UTF-8 NSJSONSerialization bytes' or receipt.get('trailingLFIncluded') is not False or receipt.get('scope') != 'original-native-json-before-fallback':
        raise ValueError('native omitted JSON byte range is unknown')
    if not receipt['available']:
        reason = receipt.get('unavailableReason')
        if kind != 'native-serialization-error' or receipt.get('bytes') is not None or receipt.get('sha256') is not None or not isinstance(reason, str) or not reason:
            raise ValueError('native unavailable original JSON cannot claim bytes or SHA')
        if original is not None: raise ValueError('original bytes contradict unavailable native receipt')
        return 'original-unavailable: ' + reason
    size, digest = receipt.get('bytes'), receipt.get('sha256')
    if kind != 'native-report-budget' or type(size) is not int or size <= 24576 or not isinstance(digest, str) or re.fullmatch('[0-9a-f]{64}', digest) is None:
        raise ValueError('native original JSON byte count or SHA is invalid')
    if original is None: return 'schema-validated; omitted original bytes unavailable to outer runner'
    if len(original) != size or hashlib.sha256(original).hexdigest() != digest:
        raise ValueError('native original JSON does not match independently retained bytes')
    original.decode('utf-8')
    return 'original-bytes-and-sha-independently-verified'


def resource_diagnostic(case):
    report = {'format': 'office-pdf-ios-resource-first-rejection-v1', 'baselineReturncode': case.baseline_returncode,
              'test': case.id(), 'baseline': case.baseline_metadata,
              'scope': 'test-only; baseline executable unchanged; raw helper/binary not exported',
              'runtime': {'python': sys.version, 'pythonExecutable': sys.executable,
                          'pythonSource': 'sys.version/sys.executable', 'macOS': platform.mac_ver()[0] or 'unknown',
                          'macOSSource': 'platform.mac_ver', 'xcode': 'unknown until actual xcodebuild -version receipt'}}
    try:
        report['baselineGeneratedFile'] = diagnostic_file(case.root / 'validator.mm')
        bundle, main = case.output / 'OfficePdfKernelResources.bundle', case.output / 'AppRootResources'
        paths = {'bundle': bundle, 'program': bundle / 'program', 'share': bundle / 'share',
                 'manifest': bundle / 'OfficePdfKernelManifest.json', 'nested': bundle / 'program/registry/test.xcd',
                 'empty': bundle / 'program/empty', 'mainRoot': main, 'mainICU': main / 'ICU.dat'}
        python_paths = {}
        for name, path in paths.items():
            value = {'input': str(path), 'realpath': os.path.realpath(path)}
            try:
                info = path.lstat()
                value['lstat'] = {key: getattr(info, key) for key in (
                    'st_dev', 'st_ino', 'st_mode', 'st_nlink', 'st_size', 'st_mtime_ns', 'st_ctime_ns')}
                value['type'] = 'directory' if stat.S_ISDIR(info.st_mode) else ('regular' if stat.S_ISREG(info.st_mode) else 'other')
                if stat.S_ISREG(info.st_mode): value['file'] = diagnostic_file(path)
            except OSError as exc:
                value['lstatError'] = {'errno': exc.errno, 'type': type(exc).__name__}
            python_paths[name] = value
        report['pythonPaths'] = python_paths
        report['fixtureManifest'] = diagnostic_file(paths['manifest'])
        with paths['manifest'].open('rb') as stream:
            manifest_raw = stream.read(4 * 1024 * 1024 + 1)
        if len(manifest_raw) > 4 * 1024 * 1024: raise ValueError('fixture manifest diagnostic byte budget')
        fixture = json.loads(manifest_raw)
        rows = fixture.get('resources', [])
        if not isinstance(rows, list) or len(rows) > 32: raise ValueError('fixture resource diagnostic row budget')
        report['resourceFiles'] = []
        for row in rows:
            relative = row['path']
            if not isinstance(relative, str) or '\\' in relative or any(part in ('', '.', '..') for part in relative.split('/')) or relative.startswith('/'):
                raise ValueError('unsafe fixture path for diagnostic')
            report['resourceFiles'].append({'path': relative, 'actual': diagnostic_file(bundle / relative),
                                            'manifestBytes': row['bytes'], 'manifestSha256': row['sha256']})
        source = (ROOT / 'src/OfficePdfKernel.mm').read_text(encoding='utf-8')
        disk = (ROOT / 'src/OfficePdfKernel.mm').read_bytes()
        disk_helper = disk[disk.index(b'bool sameResourceStat('):disk.index('// Kit对象只在持锁工作线程'.encode())]
        report['originalDiskSource'] = {'bytes': len(disk), 'sha256': hashlib.sha256(disk).hexdigest(),
                                        'helperBytes': len(disk_helper), 'helperSha256': hashlib.sha256(disk_helper).hexdigest(),
                                        'generatedHashRepresentation': 'UTF-8 of original universal-newline text extraction'}
        program, metadata = validator_program(source, diagnostic=True)
        report['diagnostic'] = metadata
        path, executable = case.root / 'validator-diagnostic.mm', case.root / 'validator-diagnostic'
        path.write_text(program, encoding='utf-8')
        report['diagnosticGeneratedFile'] = diagnostic_file(path)
        compile_result = diagnostic_command(['xcrun', 'clang++', '-std=c++17', '-Oz', '-fobjc-arc', '-framework', 'Foundation',
                                             str(path), '-o', str(executable)], 30)
        report['diagnosticCompile'] = compile_result
        report['runtime']['xcode'] = diagnostic_command(['xcodebuild', '-version'], 5)
        report['runtime']['xcodeSource'] = 'actual xcodebuild -version result'
        if compile_result['returncode'] != 0:
            raise ValueError('diagnostic compile failed')
        result = diagnostic_command([str(executable), str(bundle), str(main)], 10, stream_limit=24577)
        report['diagnosticRun'] = result
        report['baselineDiagnosticMismatch'] = result['returncode'] != case.baseline_returncode
        if not result['stdout']['complete']: raise ValueError('native JSON exceeds diagnostic stream budget')
        native = json.loads(result['stdout']['text'])
        if not isinstance(native, dict): raise ValueError('native JSON is not object')
        report['native'] = native
        omission = validate_native_omission(native)
        if omission is not None: report['nativeOmissionBinding'] = omission
        # 原生结构仅保存一次；原stdout的长度/SHA仍绑定真实子进程输出。
        report['diagnosticRun'] = {**result, 'stdout': {key: value for key, value in result['stdout'].items() if key != 'text'}}
        first = native.get('firstReject')
        if first is not None:
            lines = source.splitlines()
            line = first.get('sourceLine') if isinstance(first, dict) else None
            if type(line) is not int or line not in metadata['returnSourceLines']:
                raise ValueError('native first rejection has unknown source mapping')
            report['firstRejectSource'] = {'line': line, 'text': lines[line - 1], 'function': first.get('function'),
                                           'mapping': 'original source return-token line; expression evaluated once'}
    except Exception as exc:
        report['diagnosticError'] = type(exc).__name__ + ': ' + str(exc)[:512]
    return report


def emit_resource_diagnostic(case):
    if RESOURCE_DIAGNOSTIC_BUDGET.exhausted: return
    try:
        report = resource_diagnostic(case)
    except Exception as exc:
        report = {'baselineReturncode': getattr(case, 'baseline_returncode', 'unknown'),
                  'diagnosticError': type(exc).__name__ + ': ' + str(exc)[:512]}
    try:
        raw = RESOURCE_DIAGNOSTIC_BUDGET.encode(report)
        if raw: print(raw.decode('ascii'), end='', flush=True)
    except Exception as exc:
        diagnostic_secondary(case, exc)


def diagnostic_secondary(case, error):
    """stdout/序列化出口失败时尝试小stderr回执，仍计入同一总预算。"""
    try:
        report = {'baselineReturncode': getattr(case, 'baseline_returncode', 'unknown'),
                  'diagnosticError': 'diagnostic-emission-failed', 'secondaryType': type(error).__name__}
        raw = b'COMPACT_RESOURCE_DIAGNOSTIC ' + json.dumps(report, separators=(',', ':')).encode('ascii') + b'\n'
        budget = RESOURCE_DIAGNOSTIC_BUDGET
        if len(raw) <= min(512, budget.per_report) and budget.used + len(raw) <= budget.total:
            budget.used += len(raw)
            sys.stderr.write(raw.decode('ascii')); sys.stderr.flush()
    except Exception:
        pass  # 两个日志流均失效时仍保留unittest原始baseline主错，不能制造可记录成功。


