    def test_same_size_change_during_fd_read_is_rejected(self):
        target = self.inputs / 'ICU.dat'
        original = os.fdopen
        class Reader:
            def __init__(self, stream): self.stream, self.changed = stream, False
            def __enter__(self): return self
            def __exit__(self, *args): return self.stream.__exit__(*args)
            def fileno(self): return self.stream.fileno()
            def read(self, count):
                raw = self.stream.read(count)
                if not self.changed:
                    self.changed = True
                    before = target.stat()
                    target.write_bytes(b'x' * IDENTITY[0])
                    os.utime(target, ns=(before.st_atime_ns, before.st_mtime_ns + 1000000000))
                return raw
        with patch.object(build.os, 'fdopen', lambda *args, **kwargs: Reader(original(*args, **kwargs))), \
                self.assertRaisesRegex(ValueError, 'changed'):
            build._resource_file(self.inputs, 'ICU.dat')

